#!/usr/bin/env python3
import os, sys, shlex, hashlib, json, time, subprocess, collections, pathlib, threading, struct, re
from concurrent.futures import ThreadPoolExecutor

VERSION = "1.14.0.git"

def get_default_jobs():
    cpu_count = None
    try:
        if hasattr(os, 'sched_getaffinity'):
            cpu_count = len(os.sched_getaffinity(0))
    except:
        pass
    if cpu_count is None:
        try:
            cpu_count = os.cpu_count() or 1
        except:
            cpu_count = 1
    cgroup_limit = None
    try:
        with open('/sys/fs/cgroup/cpu.max','r') as f:
            parts = f.read().strip().split()
            if len(parts)>=2 and parts[0]!='max':
                quota=int(parts[0]); period=int(parts[1])
                if period>0 and quota>0:
                    cgroup_limit = (quota + period -1)//period
    except:
        pass
    if cgroup_limit is None:
        try:
            with open('/sys/fs/cgroup/cpu/cpu.cfs_quota_us','r') as f:
                quota=int(f.read().strip())
            with open('/sys/fs/cgroup/cpu/cpu.cfs_period_us','r') as f:
                period=int(f.read().strip())
            if quota>0 and period>0:
                cgroup_limit = (quota + period -1)//period
        except:
            pass
    if cgroup_limit is not None:
        cpu_count = min(cpu_count, cgroup_limit)
    return cpu_count + 2

DEFAULT_JOBS = get_default_jobs()

class ParseError(Exception):
    def __init__(self, filename, lineno, msg, line=""):
        self.filename = filename
        self.lineno = lineno
        self.msg = msg
        self.line = line
        super().__init__(self.format_msg())

    def format_msg(self):
        if self.line:
            # Try to produce caret pointing: for simplicity, if message mentions token, find it?
            # We'll produce line and caret at 0? Original shows caret under problematic token.
            # For many errors, caret is at specific column. We need to approximate to match original.
            # We'll try to find position of relevant token in line if possible.
            # For "expected ':', got newline" error, caret is at end.
            # For "unknown build rule", caret is under rule name?
            # For duplicate rule, caret under rule name?
            # For simplicity, we will place caret at the start of the problematic part if we can find, else at end.
            # The original format: "<file>:<line>: <msg>\n<line-content>\n<spaces>^ near here"
            # We'll attempt to find column.
            return f"{self.filename}:{self.lineno}: {self.msg}\n{self.line}\n{' '*len(self.line)}^ near here"
        else:
            return f"{self.filename}:{self.lineno}: {self.msg}"

def expand_vars(raw, vars_dict, required_version, filename, lineno, line_content):
    res = []
    i = 0
    while i < len(raw):
        c = raw[i]
        if c != '$':
            res.append(c)
            i+=1
            continue
        if i+1 >= len(raw):
            raise ParseError(filename, lineno, "bad $-escape (literal $ must be written as $$)", line_content)
        nc = raw[i+1]
        if nc == '$':
            res.append('$')
            i+=2
        elif nc == ' ':
            res.append(' ')
            i+=2
        elif nc == ':':
            res.append(':')
            i+=2
        elif nc == '^':
            if required_version is None or required_version < (1,14):
                raise ParseError(filename, lineno, "using $^ escape requires specifying 'ninja_required_version' with version greater or equal 1.14", line_content)
            res.append('\n')
            i+=2
        elif nc == '\n':
            i+=2
            while i < len(raw) and raw[i] in ' \t':
                i+=1
        elif nc == '{':
            end = raw.find('}', i+1)
            if end == -1:
                raise ParseError(filename, lineno, "bad $-escape (literal $ must be written as $$)", line_content)
            var_name = raw[i+2:end]
            res.append(vars_dict.get(var_name, ''))
            i = end+1
        else:
            j = i+1
            while j < len(raw) and (raw[j].isalnum() or raw[j] in '_-'):
                j+=1
            if j == i+1:
                raise ParseError(filename, lineno, "bad $-escape (literal $ must be written as $$)", line_content)
            var_name = raw[i+1:j]
            res.append(vars_dict.get(var_name, ''))
            i = j
    return ''.join(res)

def tokenize_paths(s, filename, lineno, line_content, required_version):
    tokens = []
    cur = []
    i = 0
    while i < len(s):
        c = s[i]
        if c == ' ' or c == '\t':
            if cur:
                tokens.append(''.join(cur))
                cur = []
            i+=1
            while i < len(s) and s[i] in ' \t':
                i+=1
            continue
        elif c == '$':
            if i+1 >= len(s):
                raise ParseError(filename, lineno, "bad $-escape (literal $ must be written as $$)", line_content)
            nc = s[i+1]
            if nc == ' ':
                cur.append(' ')
                i+=2
            elif nc == ':':
                cur.append(':')
                i+=2
            elif nc == '$':
                cur.append('$$')
                i+=2
            elif nc == '^':
                if required_version is None or required_version < (1,14):
                    raise ParseError(filename, lineno, "using $^ escape requires specifying 'ninja_required_version' with version greater or equal 1.14", line_content)
                cur.append('\n')
                i+=2
            elif nc == '{':
                end = s.find('}', i+1)
                if end == -1:
                    raise ParseError(filename, lineno, "bad $-escape (literal $ must be written as $$)", line_content)
                cur.append(s[i:end+1])
                i = end+1
            else:
                j = i+1
                while j < len(s) and (s[j].isalnum() or s[j] in '_-'):
                    j+=1
                if j == i+1:
                    raise ParseError(filename, lineno, "bad $-escape (literal $ must be written as $$)", line_content)
                cur.append(s[i:j])
                i = j
        else:
            cur.append(c)
            i+=1
    if cur:
        tokens.append(''.join(cur))
    return tokens

def shell_quote(p):
    return shlex.quote(p)

class Pool:
    def __init__(self, name, depth, filename="", lineno=0):
        self.name = name
        self.depth = depth
        self.filename = filename
        self.lineno = lineno
        self.vars = {}

class Rule:
    def __init__(self, name, filename="", lineno=0):
        self.name = name
        self.filename = filename
        self.lineno = lineno
        self.vars = {}

class Edge:
    def __init__(self, outputs, implicit_outputs, rule_name, inputs, implicit_inputs, order_only, validations, variables, filename, lineno):
        self.outputs = outputs
        self.implicit_outputs = implicit_outputs
        self.rule_name = rule_name
        self.inputs = inputs
        self.implicit_inputs = implicit_inputs
        self.order_only = order_only
        self.validations = validations
        self.variables = variables
        self.filename = filename
        self.lineno = lineno
        self.pool_name = None
        self.depfile = None
        self.deps = None
        self.dyndep = None
        self.restat = False
        self.generator = False
        self.rspfile = None
        self.rspfile_content = None
        self.description = None
        self.command = None

class FileContext:
    def __init__(self, path, parent=None):
        self.path = path
        self.vars = {}
        self.rules = {}
        self.pools = {}
        self.parent = parent

    def lookup_var_dict(self):
        d = {}
        chain = []
        ctx = self
        while ctx is not None:
            chain.append(ctx)
            ctx = ctx.parent
        for ctx in reversed(chain):
            d.update(ctx.vars)
        return d

    def lookup_rule(self, name):
        ctx = self
        while ctx is not None:
            if name in ctx.rules:
                return ctx.rules[name]
            ctx = ctx.parent
        return None

    def lookup_pool(self, name, global_pools):
        ctx = self
        while ctx is not None:
            if name in ctx.pools:
                return ctx.pools[name]
            ctx = ctx.parent
        if name in global_pools:
            return global_pools[name]
        return None

class Parser:
    def __init__(self, root_file):
        self.root_file = root_file
        self.global_pools = {'console': Pool('console', 1, '', 0)}
        self.file_context_stack = []
        self.edges = []
        self.defaults = []
        self.required_version = None
        self.builddir = None
        self.outputs_seen = {}  # output -> edge
        self.includes_visited = set()

    def parse(self):
        abs_root = os.path.abspath(self.root_file)
        root_ctx = FileContext(abs_root, parent=None)
        self.file_context_stack.append(root_ctx)
        self._parse_file(abs_root, root_ctx)
        return self

    def _resolve_path(self, current_file_path, include_path):
        base_dir = os.path.dirname(current_file_path)
        if os.path.isabs(include_path):
            return include_path
        return os.path.normpath(os.path.join(base_dir, include_path))

    def _read_logical_lines(self, filepath):
        try:
            with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
                physical = f.readlines()
        except FileNotFoundError:
            raise ParseError(filepath, 1, f"loading '{filepath}': No such file or directory", "")

        logical = []
        cur = ""
        cur_start = 1
        pending = False
        for idx, pline in enumerate(physical):
            raw = pline.rstrip('\r\n')
            cnt = 0
            for ch in reversed(raw):
                if ch == '$':
                    cnt+=1
                else:
                    break
            is_cont = (cnt % 2 == 1)
            if is_cont:
                raw_wo = raw[:-1]
                if pending:
                    cur += raw_wo
                else:
                    cur = raw_wo
                    cur_start = idx+1
                pending = True
                continue
            else:
                if pending:
                    stripped = raw.lstrip(' \t')
                    cur += stripped
                    logical.append((cur, cur_start, filepath))
                    cur = ""
                    pending = False
                else:
                    logical.append((raw, idx+1, filepath))
        if pending:
            logical.append((cur, cur_start, filepath))
        return logical

    def _parse_file(self, filepath, context):
        logical_lines = self._read_logical_lines(filepath)

        # indent stack: list of (indent, type, obj)
        indent_stack = [(-1, 'file', context)]

        for text, lineno, fpath in logical_lines:
            # compute indent
            indent = 0
            for ch in text:
                if ch in ' \t':
                    indent+=1
                else:
                    break
            stripped = text.lstrip(' \t')
            if stripped == "":
                continue
            if stripped.startswith('#'):
                continue

            # pop while indent <= top
            while indent_stack and indent <= indent_stack[-1][0]:
                indent_stack.pop()
            if not indent_stack:
                indent_stack.append((-1, 'file', context))

            parent_indent, parent_type, parent_obj = indent_stack[-1]

            if parent_type == 'file' and indent != 0:
                raise ParseError(fpath, lineno, "unexpected indent", text)

            if parent_type in ('rule','build','pool'):
                # must be var assignment
                if '=' not in stripped:
                    raise ParseError(fpath, lineno, "expected '=', got identifier", text)
                eq_idx = stripped.find('=')
                var_name = stripped[:eq_idx].strip()
                var_value_raw = stripped[eq_idx+1:].lstrip(' \t')
                visible = context.lookup_var_dict()
                if parent_type == 'rule':
                    parent_obj.vars[var_name] = var_value_raw
                elif parent_type == 'build':
                    # expand immediately using visible + already defined build vars
                    visible2 = dict(visible)
                    visible2.update(parent_obj.variables)
                    try:
                        expanded = expand_vars(var_value_raw, visible2, self.required_version, fpath, lineno, text)
                    except ParseError as e:
                        raise e
                    parent_obj.variables[var_name] = expanded
                else: # pool
                    try:
                        expanded = expand_vars(var_value_raw, visible, self.required_version, fpath, lineno, text)
                    except ParseError as e:
                        raise e
                    parent_obj.vars[var_name] = expanded
                    if var_name == 'depth':
                        try:
                            depth = int(expanded)
                        except:
                            # allow? parse error? Original would error? Let's try.
                            depth = 0
                        parent_obj.depth = depth
                continue

            # Top-level
            if stripped.startswith('rule '):
                rest = stripped[5:].strip()
                if not rest:
                    raise ParseError(fpath, lineno, "expected rule name", text)
                # rule name is first token, rest should be empty
                # Extract rule name as first word (before space)
                m = re.match(r'^(\S+)', rest)
                if not m:
                    raise ParseError(fpath, lineno, "expected rule name", text)
                rule_name = m.group(1)
                # Check duplicate in this file context
                if rule_name in context.rules:
                    raise ParseError(fpath, lineno, f"duplicate rule '{rule_name}'", text)
                # Also check if rule is phony? phony is built-in, but defining it should error? Let's see original: if we define rule phony, what happens?
                # Test quickly: original ninja with "rule phony" and command? It might error duplicate? Let's not enforce for phony unless already defined.
                if rule_name in context.rules:
                    raise ParseError(fpath, lineno, f"duplicate rule '{rule_name}'", text)
                # Check global? For rules, file-scoped allows duplicate across files, so not check global
                rule_obj = Rule(rule_name, fpath, lineno)
                context.rules[rule_name] = rule_obj
                indent_stack.append((indent, 'rule', rule_obj))
            elif stripped.startswith('pool '):
                rest = stripped[5:].strip()
                if not rest:
                    raise ParseError(fpath, lineno, "expected pool name", text)
                m = re.match(r'^(\S+)', rest)
                pool_name = m.group(1) if m else rest.split()[0]
                # Check duplicate pool visible
                # Look up in context chain and global
                ctx = context
                found = False
                while ctx is not None:
                    if pool_name in ctx.pools:
                        found = True
                        break
                    ctx = ctx.parent
                if pool_name in self.global_pools:
                    found = True
                if found:
                    raise ParseError(fpath, lineno, f"duplicate pool '{pool_name}'", text)
                pool_obj = Pool(pool_name, 0, fpath, lineno)
                context.pools[pool_name] = pool_obj
                self.global_pools[pool_name] = pool_obj
                indent_stack.append((indent, 'pool', pool_obj))
            elif stripped.startswith('build '):
                build_content = stripped[6:]
                # find unescaped colon
                colon_idx = -1
                i = 0
                while i < len(build_content):
                    if build_content[i] == '$' and i+1 < len(build_content):
                        i+=2
                        continue
                    if build_content[i] == ':':
                        colon_idx = i
                        break
                    i+=1
                if colon_idx == -1:
                    raise ParseError(fpath, lineno, "expected ':', got newline ($ also escapes ':')", text)
                outputs_part = build_content[:colon_idx].strip()
                rule_inputs_part = build_content[colon_idx+1:].strip()

                # outputs
                if '|' in outputs_part:
                    explicit_str, implicit_str = outputs_part.split('|',1)
                else:
                    explicit_str = outputs_part
                    implicit_str = ""
                try:
                    explicit_raw = tokenize_paths(explicit_str, fpath, lineno, text, self.required_version) if explicit_str.strip() else []
                    implicit_raw = tokenize_paths(implicit_str, fpath, lineno, text, self.required_version) if implicit_str.strip() else []
                except ParseError as e:
                    raise e

                visible = context.lookup_var_dict()
                explicit_outputs = []
                for tok in explicit_raw:
                    try:
                        exp = expand_vars(tok, visible, self.required_version, fpath, lineno, text)
                    except ParseError as e:
                        raise e
                    if exp != "":
                        explicit_outputs.append(exp)
                implicit_outputs = []
                for tok in implicit_raw:
                    try:
                        exp = expand_vars(tok, visible, self.required_version, fpath, lineno, text)
                    except ParseError as e:
                        raise e
                    if exp != "":
                        implicit_outputs.append(exp)

                if not explicit_outputs and not implicit_outputs:
                    raise ParseError(fpath, lineno, "expected path", text)

                # rule_inputs
                # Tokenize
                try:
                    raw_tokens = tokenize_paths(rule_inputs_part, fpath, lineno, text, self.required_version)
                except ParseError as e:
                    raise e
                if not raw_tokens:
                    raise ParseError(fpath, lineno, "expected build command name", text)
                rule_name_raw = raw_tokens[0]
                try:
                    rule_name = expand_vars(rule_name_raw, visible, self.required_version, fpath, lineno, text)
                except ParseError as e:
                    raise e
                # Check rule exists (except phony)
                if rule_name != 'phony':
                    if context.lookup_rule(rule_name) is None:
                        raise ParseError(fpath, lineno, f"unknown build rule '{rule_name}'", text)

                explicit_inputs_raw = []
                implicit_inputs_raw = []
                order_only_raw = []
                validations_raw = []
                cur_section = 'explicit'
                for tok in raw_tokens[1:]:
                    if tok == '|':
                        cur_section = 'implicit'
                    elif tok == '||':
                        cur_section = 'order_only'
                    elif tok == '|@':
                        cur_section = 'validations'
                    else:
                        if cur_section == 'explicit':
                            explicit_inputs_raw.append(tok)
                        elif cur_section == 'implicit':
                            implicit_inputs_raw.append(tok)
                        elif cur_section == 'order_only':
                            order_only_raw.append(tok)
                        else:
                            validations_raw.append(tok)

                explicit_inputs = []
                for tok in explicit_inputs_raw:
                    exp = expand_vars(tok, visible, self.required_version, fpath, lineno, text)
                    if exp != "":
                        explicit_inputs.append(exp)
                implicit_inputs = []
                for tok in implicit_inputs_raw:
                    exp = expand_vars(tok, visible, self.required_version, fpath, lineno, text)
                    if exp != "":
                        implicit_inputs.append(exp)
                order_only = []
                for tok in order_only_raw:
                    exp = expand_vars(tok, visible, self.required_version, fpath, lineno, text)
                    if exp != "":
                        order_only.append(exp)
                validations = []
                for tok in validations_raw:
                    exp = expand_vars(tok, visible, self.required_version, fpath, lineno, text)
                    if exp != "":
                        validations.append(exp)

                edge = Edge(explicit_outputs, implicit_outputs, rule_name, explicit_inputs, implicit_inputs, order_only, validations, {}, fpath, lineno)

                # Check duplicate outputs
                for out in explicit_outputs + implicit_outputs:
                    if out in self.outputs_seen:
                        raise ParseError(fpath, lineno, f"multiple rules generate {out}", text)
                for out in explicit_outputs + implicit_outputs:
                    self.outputs_seen[out] = edge

                self.edges.append(edge)
                indent_stack.append((indent, 'build', edge))
            elif stripped.startswith('include '):
                inc_raw = stripped[8:].strip()
                try:
                    tokens = tokenize_paths(inc_raw, fpath, lineno, text, self.required_version)
                except ParseError as e:
                    raise e
                if not tokens:
                    raise ParseError(fpath, lineno, f"loading '': No such file or directory", text)
                visible = context.lookup_var_dict()
                inc_path = expand_vars(tokens[0], visible, self.required_version, fpath, lineno, text)
                if inc_path == "":
                    raise ParseError(fpath, lineno, f"loading '': No such file or directory", text)
                resolved = self._resolve_path(fpath, inc_path)
                if not os.path.exists(resolved):
                    raise ParseError(fpath, lineno, f"loading '{inc_path}': No such file or directory", text)
                # include in same context
                self._parse_file(resolved, context)
            elif stripped.startswith('subninja '):
                sub_raw = stripped[9:].strip()
                try:
                    tokens = tokenize_paths(sub_raw, fpath, lineno, text, self.required_version)
                except ParseError as e:
                    raise e
                if not tokens:
                    raise ParseError(fpath, lineno, f"loading '': No such file or directory", text)
                visible = context.lookup_var_dict()
                sub_path = expand_vars(tokens[0], visible, self.required_version, fpath, lineno, text)
                if sub_path == "":
                    raise ParseError(fpath, lineno, f"loading '': No such file or directory", text)
                resolved = self._resolve_path(fpath, sub_path)
                if not os.path.exists(resolved):
                    raise ParseError(fpath, lineno, f"loading '{sub_path}': No such file or directory", text)
                new_ctx = FileContext(resolved, parent=context)
                self._parse_file(resolved, new_ctx)
            elif stripped.startswith('default '):
                rest = stripped[8:].strip()
                if not rest:
                    raise ParseError(fpath, lineno, "expected target name", text)
                try:
                    tokens_raw = tokenize_paths(rest, fpath, lineno, text, self.required_version)
                except ParseError as e:
                    raise e
                visible = context.lookup_var_dict()
                targets = []
                for tok in tokens_raw:
                    exp = expand_vars(tok, visible, self.required_version, fpath, lineno, text)
                    if exp != "":
                        targets.append(exp)
                for t in targets:
                    if t not in self.outputs_seen:
                        raise ParseError(fpath, lineno, f"unknown target '{t}'", text)
                self.defaults.extend(targets)
            elif '=' in stripped:
                eq_idx = stripped.find('=')
                var_name = stripped[:eq_idx].strip()
                var_value_raw = stripped[eq_idx+1:].lstrip(' \t')
                visible = context.lookup_var_dict()
                try:
                    expanded = expand_vars(var_value_raw, visible, self.required_version, fpath, lineno, text)
                except ParseError as e:
                    raise e
                if var_name == 'ninja_required_version':
                    ver_str = expanded.strip()
                    m = re.match(r'^(\d+)\.(\d+)', ver_str)
                    if m:
                        major = int(m.group(1)); minor = int(m.group(2))
                        req = (major, minor)
                        cur = (1,14)
                        if req > cur:
                            sys.stderr.write(f"ninja: fatal: ninja version ({VERSION}) incompatible with build file ninja_required_version version ({ver_str}).\n")
                            sys.exit(1)
                        if req[0] != cur[0]:
                            sys.stderr.write(f"ninja: warning: ninja executable version ({VERSION}) greater than build file ninja_required_version ({ver_str}); versions may be incompatible.\n")
                        if self.required_version is None or req > self.required_version:
                            self.required_version = req
                    context.vars[var_name] = expanded
                    if var_name == 'builddir':
                        self.builddir = expanded
                else:
                    context.vars[var_name] = expanded
                    if var_name == 'builddir':
                        self.builddir = expanded
            else:
                raise ParseError(fpath, lineno, f"unknown statement", text)

