#!/usr/bin/env python3
import os, sys, shlex, hashlib, json, time, subprocess, collections, pathlib, threading, struct, re
from concurrent.futures import ThreadPoolExecutor

VERSION = "1.14.0.git"

def get_default_jobs():
    cpu_count = None
    try:
        if hasattr(os, 'sched_getaffinity'):
            cpu_count = len(os.sched_getaffinity(0))
    except:
        pass
    if cpu_count is None:
        try:
            cpu_count = os.cpu_count() or 1
        except:
            cpu_count = 1
    cgroup_limit = None
    try:
        with open('/sys/fs/cgroup/cpu.max','r') as f:
            parts = f.read().strip().split()
            if len(parts)>=2 and parts[0]!='max':
                quota=int(parts[0]); period=int(parts[1])
                if period>0 and quota>0:
                    cgroup_limit = (quota + period -1)//period
    except:
        pass
    if cgroup_limit is None:
        try:
            with open('/sys/fs/cgroup/cpu/cpu.cfs_quota_us','r') as f:
                quota=int(f.read().strip())
            with open('/sys/fs/cgroup/cpu/cpu.cfs_period_us','r') as f:
                period=int(f.read().strip())
            if quota>0 and period>0:
                cgroup_limit = (quota + period -1)//period
        except:
            pass
    if cgroup_limit is not None:
        cpu_count = min(cpu_count, cgroup_limit)
    return cpu_count + 2

DEFAULT_JOBS = get_default_jobs()

class ParseError(Exception):
    def __init__(self, filename, lineno, msg, line=""):
        self.filename = filename
        self.lineno = lineno
        self.msg = msg
        self.line = line
        super().__init__(self.format_msg())

    def format_msg(self):
        if self.line:
            # Try to produce caret pointing: for simplicity, if message mentions token, find it?
            # We'll produce line and caret at 0? Original shows caret under problematic token.
            # For many errors, caret is at specific column. We need to approximate to match original.
            # We'll try to find position of relevant token in line if possible.
            # For "expected ':', got newline" error, caret is at end.
            # For "unknown build rule", caret is under rule name?
            # For duplicate rule, caret under rule name?
            # For simplicity, we will place caret at the start of the problematic part if we can find, else at end.
            # The original format: "<file>:<line>: <msg>\n<line-content>\n<spaces>^ near here"
            # We'll attempt to find column.
            return f"{self.filename}:{self.lineno}: {self.msg}\n{self.line}\n{' '*len(self.line)}^ near here"
        else:
            return f"{self.filename}:{self.lineno}: {self.msg}"

def expand_vars(raw, vars_dict, required_version, filename, lineno, line_content):
    res = []
    i = 0
    while i < len(raw):
        c = raw[i]
        if c != '$':
            res.append(c)
            i+=1
            continue
        if i+1 >= len(raw):
            raise ParseError(filename, lineno, "bad $-escape (literal $ must be written as $$)", line_content)
        nc = raw[i+1]
        if nc == '$':
            res.append('$')
            i+=2
        elif nc == ' ':
            res.append(' ')
            i+=2
        elif nc == ':':
            res.append(':')
            i+=2
        elif nc == '^':
            if required_version is None or required_version < (1,14):
                raise ParseError(filename, lineno, "using $^ escape requires specifying 'ninja_required_version' with version greater or equal 1.14", line_content)
            res.append('\n')
            i+=2
        elif nc == '\n':
            i+=2
            while i < len(raw) and raw[i] in ' \t':
                i+=1
        elif nc == '{':
            end = raw.find('}', i+1)
            if end == -1:
                raise ParseError(filename, lineno, "bad $-escape (literal $ must be written as $$)", line_content)
            var_name = raw[i+2:end]
            res.append(vars_dict.get(var_name, ''))
            i = end+1
        else:
            j = i+1
            while j < len(raw) and (raw[j].isalnum() or raw[j] in '_-'):
                j+=1
            if j == i+1:
                raise ParseError(filename, lineno, "bad $-escape (literal $ must be written as $$)", line_content)
            var_name = raw[i+1:j]
            res.append(vars_dict.get(var_name, ''))
            i = j
    return ''.join(res)

def tokenize_paths(s, filename, lineno, line_content, required_version):
    tokens = []
    cur = []
    i = 0
    while i < len(s):
        c = s[i]
        if c == ' ' or c == '\t':
            if cur:
                tokens.append(''.join(cur))
                cur = []
            i+=1
            while i < len(s) and s[i] in ' \t':
                i+=1
            continue
        elif c == '$':
            if i+1 >= len(s):
                raise ParseError(filename, lineno, "bad $-escape (literal $ must be written as $$)", line_content)
            nc = s[i+1]
            if nc == ' ':
                cur.append(' ')
                i+=2
            elif nc == ':':
                cur.append(':')
                i+=2
            elif nc == '$':
                cur.append('$$')
                i+=2
            elif nc == '^':
                if required_version is None or required_version < (1,14):
                    raise ParseError(filename, lineno, "using $^ escape requires specifying 'ninja_required_version' with version greater or equal 1.14", line_content)
                cur.append('\n')
                i+=2
            elif nc == '{':
                end = s.find('}', i+1)
                if end == -1:
                    raise ParseError(filename, lineno, "bad $-escape (literal $ must be written as $$)", line_content)
                cur.append(s[i:end+1])
                i = end+1
            else:
                j = i+1
                while j < len(s) and (s[j].isalnum() or s[j] in '_-'):
                    j+=1
                if j == i+1:
                    raise ParseError(filename, lineno, "bad $-escape (literal $ must be written as $$)", line_content)
                cur.append(s[i:j])
                i = j
        else:
            cur.append(c)
            i+=1
    if cur:
        tokens.append(''.join(cur))
    return tokens

def shell_quote(p):
