                        if req[0] != cur[0]:
                            sys.stderr.write(f"ninja: warning: ninja executable version ({VERSION}) greater than build file ninja_required_version ({ver_str}); versions may be incompatible.\n")
                        if self.required_version is None or req > self.required_version:
                            self.required_version = req
                    context.vars[var_name] = expanded
                    if var_name == 'builddir':
                        self.builddir = expanded
                else:
                    context.vars[var_name] = expanded
                    if var_name == 'builddir':
                        self.builddir = expanded
            else:
                raise ParseError(fpath, lineno, f"unknown statement", text)

