            cnt = 0
            for ch in reversed(raw):
                if ch == '$':
                    cnt+=1
                else:
                    break
            is_cont = (cnt % 2 == 1)
            if is_cont:
                raw_wo = raw[:-1]
                if pending:
                    cur += raw_wo
                else:
                    cur = raw_wo
                    cur_start = idx+1
                pending = True
                continue
            else:
                if pending:
                    stripped = raw.lstrip(' \t')
                    cur += stripped
                    logical.append((cur, cur_start, filepath))
                    cur = ""
                    pending = False
