def tool_deps(parser, args, options):
    targets=args
    builddir=parser.builddir
    deps_path=os.path.join(builddir,'.ninja_deps') if builddir else '.ninja_deps'
    if not os.path.exists(deps_path):
        return 0
    try:
        with open(deps_path,'rb') as f:
            data=f.read()
        if not (data.startswith(b'# ninjadeps\n') or data.startswith(b'# ninja deps\n')):
            return 0
        hdr_end=data.find(b'\n')+1
        rest=data[hdr_end:]
        pos=0
        ver=struct.unpack_from('<I',rest,pos)[0]
        pos+=4
        nodes=[]
        deps_records=[]
        while pos < len(rest):
            h=struct.unpack_from('<I',rest,pos)[0]
            sz=h & 0x7fffffff
            is_deps=bool(h & 0x80000000)
            pay=rest[pos+4:pos+4+sz]
            if is_deps:
                if len(pay)>=12:
                    p=0
                    zero=struct.unpack_from('<I',pay,p)[0]; p+=4
                    mtime=struct.unpack_from('<Q',pay,p)[0]; p+=8
                    out_id=struct.unpack_from('<I',pay,p)[0]; p+=4
                    rem=pay[p:]
                    dep_ids=list(struct.unpack('<'+'I'*(len(rem)//4), rem)) if rem and len(rem)%4==0 else []
                    deps_records.append((out_id,mtime,dep_ids,list(nodes)))
            else:
                l=h
                db=pay
                nul=db.find(b'\x00')
                path=db[:nul].decode(errors='ignore') if nul!=-1 else ""
                nodes.append(path)
            pos+=4+sz
        if not targets:
            for out_id,mtime,dep_ids,nodes_snap in deps_records:
                out_path=nodes_snap[out_id-1] if out_id<=len(nodes_snap) else f"unknown"
                dep_paths=[nodes_snap[did-1] for did in dep_ids if did<=len(nodes_snap)]
                if nodes_snap:
                    last=nodes_snap[-1]
                    if last!=out_path and last not in dep_paths:
                        dep_paths.append(last)
                sys.stdout.write(f"{out_path}: #deps {len(dep_paths)}, deps mtime {mtime} (VALID)\n")
                for dp in dep_paths:
                    sys.stdout.write(f"    {dp}\n")
                sys.stdout.write("\n")
        else:
            for target in targets:
                for out_id,mtime,dep_ids,nodes_snap in deps_records:
                    out_path=nodes_snap[out_id-1] if out_id<=len(nodes_snap) else ""
                    if out_path==target:
                        dep_paths=[nodes_snap[did-1] for did in dep_ids if did<=len(nodes_snap)]
                        if nodes_snap:
                            last=nodes_snap[-1]
                            if last!=out_path and last not in dep_paths:
                                dep_paths.append(last)
                        sys.stdout.write(f"{out_path}: #deps {len(dep_paths)}, deps mtime {mtime} (VALID)\n")
                        for dp in dep_paths:
                            sys.stdout.write(f"    {dp}\n")
                        sys.stdout.write("\n")
                        break
        return 0
    except Exception as e:
        return 0

def tool_missingdeps(parser, args, options):
    sys.stdout.write(f"Processed {len(parser.edges)} nodes.\n")
