    builddir=parser.builddir
    log_path=os.path.join(builddir,'.ninja_log') if builddir else '.ninja_log'
    log_entries=load_ninja_log(log_path)
    current=set(parser.outputs_seen.keys())
    dead=[out for out in log_entries.keys() if out not in current]
    if not options.get('quiet'):
        sys.stdout.write(f"Cleaning... {len(dead)} files.\n")
    for f in dead:
        if os.path.exists(f):
            if verbose:
