def main():
    args=sys.argv[1:]
    if '--version' in args:
        sys.stdout.write(f"{VERSION}\n")
        sys.exit(0)
    if '-h' in args or '--help' in args:
        print_usage()
        sys.exit(1)

    build_dir=None
    build_file='build.ninja'
    jobs=DEFAULT_JOBS
    keep_going=1
    dry_run=False
    verbose=False
    quiet=False
    debug_modes=[]
    warning_flags=[]
    tool_name=None
    tool_args=[]
    i=0
    while i < len(args):
        arg=args[i]
        if arg=='-C':
            if i+1>=len(args):
                sys.stderr.write(f"{sys.argv[0]}: option requires an argument -- 'C'\n")
                print_usage()
                sys.exit(1)
            build_dir=args[i+1]
            i+=2
        elif arg.startswith('-C') and len(arg)>2:
            build_dir=arg[2:]
            i+=1
        elif arg=='-f':
            if i+1>=len(args):
                sys.stderr.write(f"{sys.argv[0]}: option requires an argument -- 'f'\n")
                print_usage()
                sys.exit(1)
            build_file=args[i+1]
            i+=2
        elif arg.startswith('-f') and len(arg)>2:
            build_file=arg[2:]
            i+=1
        elif arg=='-j':
            if i+1>=len(args):
                sys.stderr.write(f"{sys.argv[0]}: option requires an argument -- 'j'\n")
                print_usage()
                sys.exit(1)
            try:
                jobs=int(args[i+1])
                if jobs<0:
                    raise ValueError()
            except:
                sys.stderr.write(f"ninja: fatal: invalid -j parameter\n")
                sys.exit(1)
            i+=2
        elif arg.startswith('-j'):
            j_arg=arg[2:]
            if j_arg=='':
                sys.stderr.write(f"{sys.argv[0]}: option requires an argument -- 'j'\n")
                print_usage()
                sys.exit(1)
            try:
                jobs=int(j_arg)
                if jobs<0:
                    raise ValueError()
            except:
                sys.stderr.write(f"ninja: fatal: invalid -j parameter\n")
                sys.exit(1)
            i+=1
        elif arg=='-k':
            if i+1>=len(args):
                sys.stderr.write(f"{sys.argv[0]}: option requires an argument -- 'k'\n")
                print_usage()
                sys.exit(1)
            try:
                keep_going=int(args[i+1])
            except:
                sys.stderr.write(f"ninja: fatal: -k parameter not numeric; did you mean -k 0?\n")
                sys.exit(1)
            i+=2
        elif arg.startswith('-k') and len(arg)>2:
            try:
                keep_going=int(arg[2:])
            except:
                sys.stderr.write(f"ninja: fatal: -k parameter not numeric; did you mean -k 0?\n")
                sys.exit(1)
            i+=1
        elif arg=='-l':
            if i+1>=len(args):
                sys.stderr.write(f"{sys.argv[0]}: option requires an argument -- 'l'\n")
                print_usage()
                sys.exit(1)
            try:
                float(args[i+1])
            except:
                pass
            i+=2
        elif arg.startswith('-l') and len(arg)>2:
            i+=1
        elif arg=='-n':
            dry_run=True
            i+=1
        elif arg=='-v' or arg=='--verbose':
            verbose=True
            i+=1
        elif arg=='--quiet':
            quiet=True
            i+=1
        elif arg=='-d':
            if i+1>=len(args):
                sys.stderr.write(f"{sys.argv[0]}: option requires an argument -- 'd'\n")
                print_usage()
                sys.exit(1)
            d_arg=args[i+1]
            if d_arg=='list':
                print_debug_list()
                sys.exit(1)
            if d_arg not in ['stats','explain','keepdepfile','keeprsp']:
                sys.stderr.write(f"ninja: error: unknown debug setting '{d_arg}'\n")
                sys.exit(1)
            debug_modes.append(d_arg)
            i+=2
        elif arg.startswith('-d') and len(arg)>2:
            d_arg=arg[2:]
