        if c!='$':
            res.append(c)
            i+=1
            continue
        if i+1>=len(raw):
            raise ParseError(filename, lineno, "bad $-escape (literal $ must be written as $$)", line_content)
        nc=raw[i+1]
        if nc=='$':
            res.append('$')
            i+=2
        elif nc==' ':
            res.append(' ')
