        return d
    def lookup_rule(self, name):
        ctx=self
        while ctx is not None:
            if name in ctx.rules:
                return ctx.rules[name]
            ctx=ctx.parent
        return None

class Parser:
    def __init__(self, root_file):
        self.root_file=root_file
        self.global_pools={'console': Pool('console',1,'',0)}
        self.edges=[]
        self.defaults=[]
        self.required_version=None
        self.builddir=None
        self.outputs_seen={}
    def parse(self):
        abs_root=os.path.abspath(self.root_file)
        root_ctx=FileContext(abs_root, parent=None)
        self._parse_file(abs_root, root_ctx)
        return self
    def _resolve_path(self, current_file_path, include_path):
        base_dir=os.path.dirname(current_file_path)
        if os.path.isabs(include_path):
            return include_path
        return os.path.normpath(os.path.join(base_dir, include_path))
    def _read_logical_lines(self, filepath):
        try:
            with open(filepath,'r',encoding='utf-8',errors='ignore') as f:
                physical=f.readlines()
        except FileNotFoundError:
            raise ParseError(filepath,1,f"loading '{filepath}': No such file or directory","")
        logical=[]
        cur=""
        cur_start=1
        pending=False
        for idx,pline in enumerate(physical):
            raw=pline.rstrip('\r\n')
            cnt=0
            for ch in reversed(raw):
                if ch=='$':
                    cnt+=1
                else:
                    break
            is_cont=(cnt%2==1)
            if is_cont:
                raw_wo=raw[:-1]
                if pending:
                    cur+=raw_wo
                else:
                    cur=raw_wo
                    cur_start=idx+1
                pending=True
                continue
            else:
                if pending:
                    stripped=raw.lstrip(' \t')
                    cur+=stripped
                    logical.append((cur,cur_start,filepath))
                    cur=""
                    pending=False
                else:
                    logical.append((raw,idx+1,filepath))
        if pending:
            logical.append((cur,cur_start,filepath))
        return logical
    def _parse_file(self, filepath, context):
        logical_lines=self._read_logical_lines(filepath)
        indent_stack=[(-1,'file',context)]
        for text,lineno,fpath in logical_lines:
            indent=0
            for ch in text:
                if ch in ' \t':
                    indent+=1
                else:
                    break
            stripped=text.lstrip(' \t')
            if stripped=="":
                continue
            if stripped.startswith('#'):
                continue
            while indent_stack and indent <= indent_stack[-1][0]:
                indent_stack.pop()
            if not indent_stack:
                indent_stack.append((-1,'file',context))
            parent_indent,parent_type,parent_obj=indent_stack[-1]
            if parent_type=='file' and indent!=0:
                raise ParseError(fpath,lineno,"unexpected indent",text)
            if parent_type in ('rule','build','pool'):
                if '=' not in stripped:
                    raise ParseError(fpath,lineno,"expected '=', got identifier",text)
                eq_idx=stripped.find('=')
                var_name=stripped[:eq_idx].strip()
                var_value_raw=stripped[eq_idx+1:].lstrip(' \t')
                visible=context.lookup_var_dict()
                if parent_type=='rule':
                    parent_obj.vars[var_name]=var_value_raw
                elif parent_type=='build':
                    visible2=dict(visible)
                    visible2.update(parent_obj.variables)
                    expanded=expand_vars(var_value_raw,visible2,self.required_version,fpath,lineno,text)
                    parent_obj.variables[var_name]=expanded
                else:
                    expanded=expand_vars(var_value_raw,visible,self.required_version,fpath,lineno,text)
                    parent_obj.vars[var_name]=expanded
                    if var_name=='depth':
                        try:
                            parent_obj.depth=int(expanded)
                        except:
                            parent_obj.depth=0
                continue
            if stripped.startswith('rule '):
                rest=stripped[5:].strip()
                if not rest:
                    raise ParseError(fpath,lineno,"expected rule name",text)
                m=re.match(r'^(\S+)',rest)
                rule_name=m.group(1) if m else rest.split()[0]
                if rule_name in context.rules:
                    raise ParseError(fpath,lineno,f"duplicate rule '{rule_name}'",text)
                rule_obj=Rule(rule_name,fpath,lineno)
                context.rules[rule_name]=rule_obj
                indent_stack.append((indent,'rule',rule_obj))
            elif stripped.startswith('pool '):
                rest=stripped[5:].strip()
                if not rest:
                    raise ParseError(fpath,lineno,"expected pool name",text)
                m=re.match(r'^(\S+)',rest)
                pool_name=m.group(1) if m else rest.split()[0]
                ctx=context
                found=False
                while ctx is not None:
                    if pool_name in ctx.pools:
                        found=True
                        break
                    ctx=ctx.parent
                if pool_name in self.global_pools:
                    found=True
                if found:
                    raise ParseError(fpath,lineno,f"duplicate pool '{pool_name}'",text)
                pool_obj=Pool(pool_name,0,fpath,lineno)
                context.pools[pool_name]=pool_obj
                self.global_pools[pool_name]=pool_obj
                indent_stack.append((indent,'pool',pool_obj))
            elif stripped.startswith('build '):
                build_content=stripped[6:]
                colon_idx=-1
                i=0
                while i < len(build_content):
                    if build_content[i]=='$' and i+1 < len(build_content):
                        i+=2
                        continue
                    if build_content[i]==':':
                        colon_idx=i
                        break
                    i+=1
                if colon_idx==-1:
                    raise ParseError(fpath,lineno,"expected ':', got newline ($ also escapes ':')",text)
                outputs_part=build_content[:colon_idx].strip()
                rule_inputs_part=build_content[colon_idx+1:].strip()
                if '|' in outputs_part:
                    explicit_str,implicit_str=outputs_part.split('|',1)
                else:
                    explicit_str=outputs_part
                    implicit_str=""
                explicit_raw=tokenize_paths(explicit_str,fpath,lineno,text,self.required_version) if explicit_str.strip() else []
                implicit_raw=tokenize_paths(implicit_str,fpath,lineno,text,self.required_version) if implicit_str.strip() else []
                visible=context.lookup_var_dict()
                explicit_outputs=[]
                for tok in explicit_raw:
                    exp=expand_vars(tok,visible,self.required_version,fpath,lineno,text)
                    if exp!="":
                        explicit_outputs.append(exp)
                implicit_outputs=[]
                for tok in implicit_raw:
                    exp=expand_vars(tok,visible,self.required_version,fpath,lineno,text)
                    if exp!="":
                        implicit_outputs.append(exp)
                if not explicit_outputs and not implicit_outputs:
                    raise ParseError(fpath,lineno,"expected path",text)
                raw_tokens=tokenize_paths(rule_inputs_part,fpath,lineno,text,self.required_version)
                if not raw_tokens:
                    raise ParseError(fpath,lineno,"expected build command name",text)
                rule_name_raw=raw_tokens[0]
                rule_name=expand_vars(rule_name_raw,visible,self.required_version,fpath,lineno,text)
                if rule_name!='phony':
                    if context.lookup_rule(rule_name) is None:
                        raise ParseError(fpath,lineno,f"unknown build rule '{rule_name}'",text)
                explicit_inputs_raw=[]
                implicit_inputs_raw=[]
                order_only_raw=[]
                validations_raw=[]
                cur_section='explicit'
                for tok in raw_tokens[1:]:
                    if tok=='|':
                        cur_section='implicit'
                    elif tok=='||':
                        cur_section='order_only'
                    elif tok=='|@':
                        cur_section='validations'
                    else:
                        if cur_section=='explicit':
                            explicit_inputs_raw.append(tok)
                        elif cur_section=='implicit':
                            implicit_inputs_raw.append(tok)
                        elif cur_section=='order_only':
                            order_only_raw.append(tok)
                        else:
                            validations_raw.append(tok)
                explicit_inputs=[]
                for tok in explicit_inputs_raw:
                    exp=expand_vars(tok,visible,self.required_version,fpath,lineno,text)
                    if exp!="":
                        explicit_inputs.append(exp)
                implicit_inputs=[]
                for tok in implicit_inputs_raw:
                    exp=expand_vars(tok,visible,self.required_version,fpath,lineno,text)
                    if exp!="":
                        implicit_inputs.append(exp)
                order_only=[]
                for tok in order_only_raw:
                    exp=expand_vars(tok,visible,self.required_version,fpath,lineno,text)
                    if exp!="":
                        order_only.append(exp)
                validations=[]
                for tok in validations_raw:
                    exp=expand_vars(tok,visible,self.required_version,fpath,lineno,text)
                    if exp!="":
                        validations.append(exp)
                edge=Edge(explicit_outputs,implicit_outputs,rule_name,explicit_inputs,implicit_inputs,order_only,validations,{},fpath,lineno,context)
                for out in explicit_outputs+implicit_outputs:
                    if out in self.outputs_seen:
                        raise ParseError(fpath,lineno,f"multiple rules generate {out}",text)
                for out in explicit_outputs+implicit_outputs:
                    self.outputs_seen[out]=edge
                self.edges.append(edge)
                indent_stack.append((indent,'build',edge))
            elif stripped.startswith('include '):
                inc_raw=stripped[8:].strip()
                tokens=tokenize_paths(inc_raw,fpath,lineno,text,self.required_version)
                if not tokens:
                    raise ParseError(fpath,lineno,f"loading '': No such file or directory",text)
                visible=context.lookup_var_dict()
                inc_path=expand_vars(tokens[0],visible,self.required_version,fpath,lineno,text)
                if inc_path=="":
                    raise ParseError(fpath,lineno,f"loading '': No such file or directory",text)
                resolved=self._resolve_path(fpath,inc_path)
                if not os.path.exists(resolved):
                    raise ParseError(fpath,lineno,f"loading '{inc_path}': No such file or directory",text)
                self._parse_file(resolved,context)
            elif stripped.startswith('subninja '):
                sub_raw=stripped[9:].strip()
                tokens=tokenize_paths(sub_raw,fpath,lineno,text,self.required_version)
                if not tokens:
                    raise ParseError(fpath,lineno,f"loading '': No such file or directory",text)
                visible=context.lookup_var_dict()
                sub_path=expand_vars(tokens[0],visible,self.required_version,fpath,lineno,text)
                if sub_path=="":
                    raise ParseError(fpath,lineno,f"loading '': No such file or directory",text)
                resolved=self._resolve_path(fpath,sub_path)
                if not os.path.exists(resolved):
                    raise ParseError(fpath,lineno,f"loading '{sub_path}': No such file or directory",text)
                new_ctx=FileContext(resolved,parent=context)
                self._parse_file(resolved,new_ctx)
            elif stripped.startswith('default '):
                rest=stripped[8:].strip()
                if not rest:
                    raise ParseError(fpath,lineno,"expected target name",text)
                tokens_raw=tokenize_paths(rest,fpath,lineno,text,self.required_version)
                visible=context.lookup_var_dict()
                targets=[]
                for tok in tokens_raw:
                    exp=expand_vars(tok,visible,self.required_version,fpath,lineno,text)
                    if exp!="":
                        targets.append(exp)
                for t in targets:
                    if t not in self.outputs_seen:
                        raise ParseError(fpath,lineno,f"unknown target '{t}'",text)
                self.defaults.extend(targets)
            elif '=' in stripped:
                eq_idx=stripped.find('=')
                var_name=stripped[:eq_idx].strip()
                var_value_raw=stripped[eq_idx+1:].lstrip(' \t')
                visible=context.lookup_var_dict()
                expanded=expand_vars(var_value_raw,visible,self.required_version,fpath,lineno,text)
                if var_name=='ninja_required_version':
                    ver_str=expanded.strip()
                    m=re.match(r'^(\d+)\.(\d+)',ver_str)
                    if m:
                        major=int(m.group(1)); minor=int(m.group(2))
                        req=(major,minor)
                        cur=(1,14)
                        if req>cur:
                            sys.stderr.write(f"ninja: fatal: ninja version ({VERSION}) incompatible with build file ninja_required_version version ({ver_str}).\n")
                            sys.exit(1)
                        if req[0]!=cur[0]:
                            sys.stderr.write(f"ninja: warning: ninja executable version ({VERSION}) greater than build file ninja_required_version ({ver_str}); versions may be incompatible.\n")
                        if self.required_version is None or req>self.required_version:
                            self.required_version=req
                    context.vars[var_name]=expanded
                    if var_name=='builddir':
                        self.builddir=expanded
                else:
                    context.vars[var_name]=expanded
                    if var_name=='builddir':
                        self.builddir=expanded
            else:
                raise ParseError(fpath,lineno,"unknown statement",text)

def hash_command(cmd):
    h=14695981039346656037
    for b in cmd.encode('utf-8',errors='ignore'):
        h ^= b
        h = (h*1099511628211) & 0xFFFFFFFFFFFFFFFF
    return f"{h:016x}"

def file_mtime_ns(path):
    try:
        return os.stat(path).st_mtime_ns
    except:
        return 0

def load_ninja_log(log_path):
    result={}
    if not os.path.exists(log_path):
        return result
    try:
        with open(log_path,'r') as f:
            lines=f.readlines()
    except:
        return result
    if not lines or not lines[0].startswith('# ninja log'):
        return result
    for line in lines[1:]:
        line=line.strip()
        if not line or line.startswith('#'):
            continue
        parts=line.split('\t')
        if len(parts)<5:
            continue
        try:
            mtime=int(parts[2])
            output=parts[3]
            h=parts[4]
            result[output]=(mtime,h)
        except:
            continue
    return result

class BuildSystem:
    def __init__(self, parser, options):
        self.parser=parser
        self.options=options
        self.global_pools=parser.global_pools
        self.edges=parser.edges
        self.defaults=parser.defaults
        self.builddir=parser.builddir
        self.outputs_map=parser.outputs_seen
        self.log_path=os.path.join(self.builddir,'.ninja_log') if self.builddir else '.ninja_log'
        self.log_entries=load_ninja_log(self.log_path)
        self.pool_limits={}
        for name,pool_obj in self.global_pools.items():
            self.pool_limits[name]=pool_obj.depth
        if 'console' not in self.pool_limits:
            self.pool_limits['console']=1
        self._display_counter=0

    def expand_edge(self, edge):
        if edge.rule_name=='phony':
            return "",{}
        rule_obj=edge.file_context.lookup_rule(edge.rule_name)
        if rule_obj is None:
            return "",{}
        file_ctx=edge.file_context
        in_quoted=' '.join(shell_quote(p) for p in edge.inputs)
        out_quoted=' '.join(shell_quote(p) for p in edge.outputs)
        builtins={'in': in_quoted, 'out': out_quoted, 'in_newline': '\n'.join(edge.inputs)}
        combined=dict(file_ctx.lookup_var_dict())
        combined.update(edge.variables)
        combined.update(builtins)
        exp_vars={}
        for k,v in rule_obj.vars.items():
            d=dict(combined)
            d.update(exp_vars)
            try:
                exp=expand_vars(v,d,self.parser.required_version,edge.filename,edge.lineno,"")
            except ParseError:
                exp=v
            exp_vars[k]=exp
        return exp_vars.get('command',''), exp_vars

    def is_edge_dirty(self, edge, built_mtimes):
        # built_mtimes: dict of outputs that have been built in this run, mapping to new mtime or old if restat didn't change
        if edge.rule_name=='phony':
            if not edge.inputs and not edge.implicit_inputs and not edge.order_only:
                for out in edge.outputs:
                    if not os.path.exists(out):
                        return True, f"output {out} doesn't exist"
                return False, ""
            # For phony with inputs, dirty if any input is dirty (i.e., its output is in built_mtimes and its mtime changed? Or if input file mtime newer than something?)
            # For simplicity, check if any input is in built_mtimes (meaning its edge was built) -> then phony should be considered dirty? Actually phony should be dirty if its inputs changed.
            # We'll check if any input is in built_mtimes (i.e., rebuilt), then phony dirty.
            for inp in edge.inputs+edge.implicit_inputs:
                if inp in built_mtimes:
                    # If input was rebuilt and its mtime changed (or it's phony)
                    return True, f"input {inp} is dirty"
            return False, ""
        for out in edge.outputs+edge.implicit_outputs:
            if not os.path.exists(out):
                return True, f"output {out} doesn't exist"
        cmd, exp_vars = self.expand_edge(edge)
        if not cmd:
            return True, "missing command"
        h=hash_command(cmd)
        for out in edge.outputs:
            if out in self.log_entries:
                old_mtime,old_hash=self.log_entries[out]
                if old_hash!=h:
                    if exp_vars.get('generator',''):
                        pass
                    else:
                        return True, f"command line changed for {out}"
        # mtime check using current file mtimes, but also considering built_mtimes for inputs that were rebuilt
        max_input_mtime=0
        for inp in edge.inputs+edge.implicit_inputs:
            # If inp was rebuilt in this run, use its new mtime from built_mtimes or from filesystem
            if inp in built_mtimes:
                m=built_mtimes[inp]
                # If restat and mtime didn't change, built_mtimes[inp] may be old mtime, so not newer
            else:
                m=file_mtime_ns(inp)
            if m>max_input_mtime:
                max_input_mtime=m
        min_output_mtime=None
        for out in edge.outputs+edge.implicit_outputs:
            m=file_mtime_ns(out)
            if min_output_mtime is None or m < min_output_mtime:
                min_output_mtime=m
        if min_output_mtime is not None and max_input_mtime>min_output_mtime:
            for inp in edge.inputs+edge.implicit_inputs:
                if inp in built_mtimes:
                    m=built_mtimes[inp]
                else:
                    m=file_mtime_ns(inp)
                if m>min_output_mtime:
                    return True, f"output {edge.outputs[0] if edge.outputs else 'unknown'} older than most recent input {inp} ({min_output_mtime} vs {m})"
        return False, ""

    def build(self, targets, jobs, verbose, quiet, dry_run, explain, keepdepfile, keeprsp):
        if not targets:
            if self.defaults:
                targets=self.defaults
            else:
                all_outputs=set(self.outputs_map.keys())
                all_inputs=set()
                for e in self.edges:
                    all_inputs.update(e.inputs)
                    all_inputs.update(e.implicit_inputs)
                    all_inputs.update(e.order_only)
                roots=[out for out in all_outputs if out not in all_inputs]
                targets=roots
        for t in targets:
            if t not in self.outputs_map and not os.path.exists(t):
                sys.stderr.write(f"ninja: error: unknown target '{t}'\n")
                sys.exit(1)
        needed_edges=set()
        visited_nodes=set()
        stack=list(targets)
        while stack:
            node=stack.pop()
            if node in visited_nodes:
                continue
            visited_nodes.add(node)
            edge=self.outputs_map.get(node)
            if edge is None:
                continue
            needed_edges.add(edge)
            for inp in edge.inputs+edge.implicit_inputs+edge.order_only:
                if inp not in visited_nodes:
                    stack.append(inp)
            for valid in edge.validations:
                if valid not in visited_nodes:
                    stack.append(valid)
        for edge in needed_edges:
            for inp in edge.inputs+edge.implicit_inputs:
                if inp not in self.outputs_map and not os.path.exists(inp):
                    sys.stderr.write(f"ninja: error: '{inp}', needed by '{edge.outputs[0] if edge.outputs else 'unknown'}', missing and no known rule to make it\n")
                    sys.exit(1)
        edge_deps={}
        for edge in needed_edges:
            deps=[]
            for inp in edge.inputs+edge.implicit_inputs+edge.order_only:
                dep_edge=self.outputs_map.get(inp)
                if dep_edge and dep_edge in needed_edges:
                    deps.append(dep_edge)
            edge_deps[edge]=deps
        in_degree={e: len(edge_deps[e]) for e in needed_edges}
        reverse=collections.defaultdict(list)
        for e,deps in edge_deps.items():
            for d in deps:
                reverse[d].append(e)
        from collections import deque
        q=deque([e for e,d in in_degree.items() if d==0])
        topo=[]
        while q:
            e=q.popleft()
            topo.append(e)
            for dep in reverse[e]:
                in_degree[dep]-=1
                if in_degree[dep]==0:
                    q.append(dep)
        if len(topo)!=len(needed_edges):
            sys.stderr.write("ninja: error: could not determine root nodes of build graph\n")
            sys.exit(1)

        # Incremental build with restat support: we will iterate topo and check dirty using built_mtimes
        built_mtimes={}  # path -> new mtime (or old if restat unchanged)
        # For initial built_mtimes, include file mtimes of source files? No.

        # We need to determine which edges are dirty in order, using built_mtimes that grows as we build.

        dirty_edges=[]
        for edge in topo:
            is_dirty,reason=self.is_edge_dirty(edge, built_mtimes)
            if is_dirty:
                dirty_edges.append(edge)
                if explain:
                    sys.stdout.write(f"ninja explain: {reason}\n")
            # else not dirty, but still its outputs mtime may be needed for future checks.
            # For non-dirty edges, we should put their outputs mtime into built_mtimes? Actually if edge not dirty, its outputs mtime is existing file mtime, which is already on disk. For future dirty checks, we will use file_mtime_ns which already reflects disk mtime. So we don't need to add to built_mtimes unless we want to handle restat? For restat, if edge is dirty but after building its output mtime didn't change, we should record old mtime in built_mtimes to indicate no change.

        if not dirty_edges and not dry_run:
            if not quiet:
                sys.stdout.write("ninja: no work to do.\n")
            return 0

        total_edges=len(dirty_edges)
        ninja_status=os.environ.get('NINJA_STATUS','[%f/%t] ')
        pool_semaphores={}
        for pname,depth in self.pool_limits.items():
            if pname=='console':
                depth=1
            if depth>0:
                pool_semaphores[pname]=threading.Semaphore(depth)
            else:
                pool_semaphores[pname]=None

        k=self.options.get('k',1)
        failures=0
        lock=threading.Lock()
        started=0
        finished=0
        running=0
        start_time=time.time()
        # For restat, track old mtimes
        old_mtimes={}
        for edge in dirty_edges:
            for out in edge.outputs+edge.implicit_outputs:
                old_mtimes[out]=file_mtime_ns(out)

        # For scheduling, we need to know which dirty edges are ready (dependencies completed)
        # We'll maintain completed set including non-dirty edges

        completed=set()
        for e in topo:
            if e not in dirty_edges:
                completed.add(e)
                for out in e.outputs+e.implicit_outputs:
                    built_mtimes[out]=file_mtime_ns(out)

        ready=[]
        for e in topo:
            if e in dirty_edges:
                if all(dep in completed for dep in edge_deps[e]):
                    ready.append(e)

        max_workers=jobs if jobs!=0 else None
        if max_workers is None or max_workers<=0:
            max_workers=len(ready)+10 if ready else 10

        remaining=set(dirty_edges)-set(ready)

        def execute_edge(edge):
            nonlocal started,finished,running,failures
            if edge.rule_name=='phony':
                with lock:
                    started+=1
                    running+=1
                    self._display_counter+=1
                    display_f=self._display_counter
                    if not quiet:
                        elapsed=time.time()-start_time
                        status_str=ninja_status.replace('%%','__PERCENT__')
                        status_str=status_str.replace('%s',str(started))
                        status_str=status_str.replace('%t',str(total_edges))
                        perc=int((display_f-1)*100/total_edges) if total_edges else 0
                        status_str=status_str.replace('%p',str(perc))
                        status_str=status_str.replace('%r',str(running))
                        status_str=status_str.replace('%u',str(total_edges-started))
                        status_str=status_str.replace('%f',str(display_f))
                        overall_rate=finished/elapsed if elapsed>0 else 0
                        status_str=status_str.replace('%o',f"{overall_rate:.1f}")
                        status_str=status_str.replace('%c',f"{overall_rate:.1f}")
                        status_str=status_str.replace('%e',f"{elapsed:.3f}")
                        if overall_rate>0:
                            eta=(total_edges-finished-1)/overall_rate if overall_rate else 0
                            status_str=status_str.replace('%E',f"{eta:.3f}")
                            def fmt_hms(s):
                                h=int(s//3600); m=int((s%3600)//60); sec=int(s%60)
                                return f"{h}:{m:02d}:{sec:02d}" if h>0 else f"{m:02d}:{sec:02d}"
                            status_str=status_status=status_str.replace('%W',fmt_hms(eta))
                        else:
                            status_str=status_str.replace('%E',"0")
                            status_str=status_str.replace('%W',"00:00")
                        def fmt_hms2(s):
                            h=int(s//3600); m=int((s%3600)//60); sec=int(s%60)
                            return f"{h}:{m:02d}:{sec:02d}" if h>0 else f"{m:02d}:{sec:02d}"
                        status_str=status_str.replace('%w',fmt_hms2(elapsed))
                        status_str=status_str.replace('%P',f"{perc}%")
                        status_str=status_str.replace('__PERCENT__','%')
                        # phony not printed
                    # ...
                with lock:
                    running-=1
                    finished+=1
                    for out in edge.outputs+edge.implicit_outputs:
                        # phony mtime = max of inputs
                        max_m=0
                        for inp in edge.inputs+edge.implicit_inputs:
                            m=built_mtimes.get(inp, file_mtime_ns(inp))
                            if m>max_m:
                                max_m=m
                        built_mtimes[out]=max_m if max_m else int(time.time()*1e9)
                return True

            cmd, exp_vars = self.expand_edge(edge)
            description=exp_vars.get('description','')
            pool_name=edge.variables.get('pool', exp_vars.get('pool',''))
            if pool_name=='':
                pool_name=None
            depfile=exp_vars.get('depfile','') or edge.variables.get('depfile','')
            rspfile=exp_vars.get('rspfile','') or edge.variables.get('rspfile','')
            rspfile_content=exp_vars.get('rspfile_content','') or edge.variables.get('rspfile_content','')
            deps=exp_vars.get('deps','') or edge.variables.get('deps','')
            if deps and not depfile:
                with lock:
                    if not quiet:
                        sys.stdout.write(f"FAILED: [code=1] {' '.join(edge.outputs)}\n")
                        sys.stdout.write(cmd+"\n")
                        sys.stdout.write("edge with deps=gcc but no depfile makes no sense\n")
                return False

            if rspfile and rspfile_content:
                try:
                    rd=os.path.dirname(rspfile)
                    if rd and not os.path.exists(rd):
                        os.makedirs(rd,exist_ok=True)
                    with open(rspfile,'w') as f:
                        f.write(rspfile_content)
                except:
                    pass
            sem=None
            if pool_name:
                sem=pool_semaphores.get(pool_name)
                if pool_name not in self.pool_limits:
                    with lock:
                        sys.stderr.write(f"ninja: error: unknown pool name '{pool_name}'\n")
                    return False
            if sem:
                sem.acquire()
            with lock:
                started+=1
                running+=1
                self._display_counter+=1
                display_f=self._display_counter
                if not quiet:
                    elapsed=time.time()-start_time
                    status_str=ninja_status.replace('%%','__PERCENT__')
                    status_str=status_str.replace('%s',str(started))
                    status_str=status_str.replace('%t',str(total_edges))
                    perc=int((display_f-1)*100/total_edges) if total_edges else 0
                    status_str=status_str.replace('%p',str(perc))
                    status_str=status_str.replace('%r',str(running))
                    status_str=status_str.replace('%u',str(total_edges-started))
                    status_str=status_str.replace('%f',str(display_f))
                    overall_rate=finished/elapsed if elapsed>0 else 0
                    status_str=status_str.replace('%o',f"{overall_rate:.1f}")
                    status_str=status_str.replace('%c',f"{overall_rate:.1f}")
                    status_str=status_str.replace('%e',f"{elapsed:.3f}")
                    if overall_rate>0:
                        eta=(total_edges-finished-1)/overall_rate if overall_rate else 0
                        status_str=status_str.replace('%E',f"{eta:.3f}")
                        def fmt_hms(s):
                            h=int(s//3600); m=int((s%3600)//60); sec=int(s%60)
                            return f"{h}:{m:02d}:{sec:02d}" if h>0 else f"{m:02d}:{sec:02d}"
                        status_str=status_str.replace('%W',fmt_hms(eta))
                    else:
                        status_str=status_str.replace('%E',"0")
                        status_str=status_str.replace('%W',"00:00")
                    def fmt_hms2(s):
                        h=int(s//3600); m=int((s%3600)//60); sec=int(s%60)
                        return f"{h}:{m:02d}:{sec:02d}" if h>0 else f"{m:02d}:{sec:02d}"
                    status_str=status_str.replace('%w',fmt_hms2(elapsed))
                    status_str=status_str.replace('%P',f"{perc}%")
                    status_str=status_str.replace('__PERCENT__','%')
                    if verbose:
                        sys.stdout.write(f"{status_str}{cmd}\n")
                    else:
                        if description:
                            sys.stdout.write(f"{status_str}{description}\n")
                        else:
                            sys.stdout.write(f"{status_str}{cmd}\n")
                    sys.stdout.flush()
            if dry_run:
                time.sleep(0.01)
                with lock:
                    running-=1
                    finished+=1
                    for out in edge.outputs+edge.implicit_outputs:
                        built_mtimes[out]=old_mtimes.get(out,0) or int(time.time()*1e9)
                if sem:
                    sem.release()
                return True
            for out in edge.outputs+edge.implicit_outputs:
                d=os.path.dirname(out)
                if d and not os.path.exists(d):
                    try:
                        os.makedirs(d,exist_ok=True)
                    except:
                        pass
            proc=subprocess.Popen(cmd,shell=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
            stdout,stderr=proc.communicate()
            retcode=proc.returncode
            if rspfile and not keeprsp:
                try:
                    os.remove(rspfile)
                except:
                    pass
            if depfile and os.path.exists(depfile) and not keepdepfile:
                try:
                    os.remove(depfile)
                except:
                    pass
            with lock:
                running-=1
                finished+=1
                if retcode!=0:
                    failures+=1
                    if not quiet:
                        sys.stdout.write(f"FAILED: [code={retcode}] {' '.join(edge.outputs)}\n")
                        sys.stdout.write(cmd+"\n")
                        if stdout:
                            sys.stdout.write(stdout.decode(errors='ignore')+"\n")
                        if stderr:
                            sys.stdout.write(stderr.decode(errors='ignore')+"\n")
                    if sem:
                        sem.release()
                    return False
                else:
                    if not quiet and (stdout or stderr):
                        if stdout:
                            sys.stdout.write(stdout.decode(errors='ignore'))
                        if stderr:
                            sys.stdout.write(stderr.decode(errors='ignore'))
                    # restat handling
                    restat_flag = exp_vars.get('restat','') or edge.variables.get('restat','')
                    is_restat = restat_flag and restat_flag not in ('0','')
                    for out in edge.outputs+edge.implicit_outputs:
                        new_mtime=file_mtime_ns(out)
                        old_mtime=old_mtimes.get(out,0)
                        if is_restat and new_mtime==old_mtime:
                            # mtime unchanged, keep old mtime in built_mtimes? Actually for restat, if mtime unchanged, we should not propagate as changed.
                            # So we set built_mtimes to old_mtime (unchanged)
                            built_mtimes[out]=old_mtime
                        else:
                            built_mtimes[out]=new_mtime
                        # Update log
                        self.log_entries[out]=(new_mtime, hash_command(cmd))
            if sem:
                sem.release()
            return True

        completed=set()
        for e in topo:
            if e not in dirty_edges:
                completed.add(e)
                for out in e.outputs+e.implicit_outputs:
                    built_mtimes[out]=file_mtime_ns(out)
        from collections import deque
        from concurrent.futures import as_completed
        with ThreadPoolExecutor(max_workers=jobs if jobs!=0 else None) as executor:
            futures={}
            for e in ready:
                futures[executor.submit(execute_edge,e)]=e
            remaining=set(dirty_edges)-set(ready)
            while futures:
                for fut in as_completed(futures):
                    edge=futures.pop(fut)
                    try:
                        success=fut.result()
                    except:
                        success=False
                    completed.add(edge)
                    if not success:
                        if k!=0 and failures>=k:
                            for ff in list(futures.keys()):
                                ff.cancel()
                            if not quiet:
                                sys.stderr.write("ninja: build stopped: subcommand failed.\n")
                            return 1
                    for rem in list(remaining):
                        if all(dep in completed for dep in edge_deps[rem]):
                            if k!=0 and failures>=k:
                                continue
                            futures[executor.submit(execute_edge,rem)]=rem
                            remaining.remove(rem)
                    break
        if failures>0:
            return 1
        try:
            ld=os.path.dirname(self.log_path)
            if ld and not os.path.exists(ld):
                os.makedirs(ld,exist_ok=True)
            with open(self.log_path,'w') as f:
                f.write("# ninja log v7\n")
                for out,(mtime,h) in self.log_entries.items():
                    f.write(f"0\t0\t{mtime}\t{out}\t{h}\n")
        except:
            pass
        return 0

# Tools

def tool_clean(parser, args, options):
    clean_generator=False
    clean_rules=False
    targets=[]
    i=0
    while i < len(args):
        arg=args[i]
        if arg=='-g':
            clean_generator=True
            i+=1
        elif arg=='-r':
            clean_rules=True
            i+=1
        elif arg.startswith('-'):
            sys.stderr.write(f"clean: invalid option -- '{arg[1]}'\n")
            sys.stderr.write("usage: ninja -t clean [options] [targets]\n\n")
            sys.stderr.write("options:\n")
            sys.stderr.write("  -g     also clean files marked as ninja generator output\n")
            sys.stderr.write("  -r     interpret targets as a list of rules to clean instead\n")
            sys.exit(1)
        else:
            targets.append(arg)
            i+=1
    all_outputs=[]
    for edge in parser.edges:
        rule_obj=edge.file_context.lookup_rule(edge.rule_name) if edge.file_context else None
        is_gen=False
        if rule_obj and rule_obj.vars.get('generator',''):
            is_gen=True
        if edge.variables.get('generator',''):
            is_gen=True
        if is_gen and not clean_generator:
            continue
        all_outputs.extend(edge.outputs)
        all_outputs.extend(edge.implicit_outputs)
    if clean_rules:
        rule_names=set(targets)
        files=[]
        for edge in parser.edges:
            if edge.rule_name in rule_names:
                rule_obj=edge.file_context.lookup_rule(edge.rule_name) if edge.file_context else None
                is_gen=False
                if rule_obj and rule_obj.vars.get('generator',''):
                    is_gen=True
                if edge.variables.get('generator',''):
                    is_gen=True
                if is_gen and not clean_generator:
                    continue
                files.extend(edge.outputs)
                files.extend(edge.implicit_outputs)
        files_to_clean=files
    else:
        if targets:
            to_clean=set()
            stack=list(targets)
            visited=set()
            while stack:
                t=stack.pop()
                if t in visited:
                    continue
                visited.add(t)
                edge=parser.outputs_seen.get(t)
                if edge:
                    for out in edge.outputs+edge.implicit_outputs:
                        to_clean.add(out)
                    for inp in edge.inputs+edge.implicit_inputs:
                        if inp in parser.outputs_seen:
                            stack.append(inp)
                else:
                    if os.path.exists(t):
                        to_clean.add(t)
            files_to_clean=list(to_clean)
        else:
            files_to_clean=all_outputs
    files_to_clean=list(set(files_to_clean))
    dry_run=options.get('dry_run',False)
    verbose=options.get('verbose',False)
    quiet=options.get('quiet',False)
    if dry_run:
        verbose=True
    if not quiet:
        sys.stdout.write(f"Cleaning... {len(files_to_clean)} files.\n")
    for f in files_to_clean:
        if os.path.exists(f):
            if verbose:
                sys.stdout.write(f"Remove {f}\n")
            if not dry_run:
                try:
                    os.remove(f)
                except:
                    pass
    return 0

def tool_targets(parser, args, options):
    if not args:
        mode='depth'
        depth=1
    else:
        if args[0]=='all':
            mode='all'
        elif args[0]=='rule':
            if len(args)<2:
                sys.stderr.write("ninja: error: expected rule name\n")
                sys.exit(1)
            mode='rule'
            rule_name=args[1]
        elif args[0]=='depth':
            if len(args)<2:
                sys.stderr.write("ninja: error: expected depth\n")
                sys.exit(1)
            try:
                depth=int(args[1])
            except:
                sys.stderr.write(f"ninja: error: invalid depth '{args[1]}'\n")
                sys.exit(1)
            mode='depth'
        else:
            if args[0].startswith('-'):
                sys.stderr.write(f"ninja: error: unknown target tool mode '{args[0]}', did you mean 'all'?\n")
            else:
                sys.stderr.write(f"ninja: error: unknown target tool mode '{args[0]}'\n")
            sys.exit(1)
    if mode=='all':
        for edge in parser.edges:
            for out in edge.outputs:
                sys.stdout.write(f"{out}: {edge.rule_name}\n")
        return 0
    elif mode=='rule':
        for edge in parser.edges:
            if edge.rule_name==rule_name:
                for out in edge.outputs:
                    sys.stdout.write(f"{out}\n")
        return 0
    else:
        all_outputs=set(parser.outputs_seen.keys())
        all_inputs=set()
        for edge in parser.edges:
            all_inputs.update(edge.inputs)
            all_inputs.update(edge.implicit_inputs)
            all_inputs.update(edge.order_only)
        roots=[out for out in all_outputs if out not in all_inputs]
        def dfs(node, cur_depth, max_depth, visited_path):
            if node in visited_path:
                return
            edge=parser.outputs_seen.get(node)
            if edge is None:
                return
            indent="  "*cur_depth if cur_depth>0 else ""
            sys.stdout.write(f"{indent}{node}: {edge.rule_name}\n")
            if max_depth!=0 and cur_depth>=max_depth:
                return
            visited_path.add(node)
            for inp in edge.inputs+edge.implicit_inputs:
                if inp in parser.outputs_seen:
                    dfs(inp, cur_depth+1, max_depth, set(visited_path))
        max_depth=depth
        if max_depth==0:
            max_depth=1000000
        for root in roots:
            dfs(root,0,max_depth,set())
        return 0

def expand_edge_command_simple(edge, parser):
    if edge.rule_name=='phony':
        return ""
    rule_obj=edge.file_context.lookup_rule(edge.rule_name)
    if rule_obj is None:
        return ""
    file_ctx=edge.file_context
    in_quoted=' '.join(shell_quote(p) for p in edge.inputs)
    out_quoted=' '.join(shell_quote(p) for p in edge.outputs)
    builtins={'in': in_quoted, 'out': out_quoted, 'in_newline': '\n'.join(edge.inputs)}
    combined=dict(file_ctx.lookup_var_dict())
    combined.update(edge.variables)
    combined.update(builtins)
    exp_vars={}
    for k,v in rule_obj.vars.items():
        d=dict(combined)
        d.update(exp_vars)
        try:
            exp=expand_vars(v,d,parser.required_version,edge.filename,edge.lineno,"")
        except ParseError:
            exp=v
        exp_vars[k]=exp
    return exp_vars.get('command','')

def tool_commands(parser, args, options):
    only_final=False
    targets=[]
    i=0
    while i < len(args):
        arg=args[i]
        if arg=='-s':
            only_final=True
            i+=1
        elif arg.startswith('-'):
            sys.stderr.write(f"commands: invalid option -- '{arg[1]}'\n")
            sys.stderr.write("usage: ninja -t commands [options] [targets]\n\n")
            sys.stderr.write("options:\n")
            sys.stderr.write("  -s     only print the final command to build [target], not the whole chain\n")
            sys.exit(1)
        else:
            targets.append(arg)
            i+=1
    if not targets:
        if parser.defaults:
            targets=parser.defaults
        else:
            all_outputs=set(parser.outputs_seen.keys())
            all_inputs=set()
            for edge in parser.edges:
                all_inputs.update(edge.inputs)
                all_inputs.update(edge.implicit_inputs)
                all_inputs.update(edge.order_only)
            roots=[out for out in all_outputs if out not in all_inputs]
            targets=roots if roots else list(all_outputs)
    all_outputs=parser.outputs_seen
    needed=set()
    visited=set()
    stack=list(targets)
    while stack:
        node=stack.pop()
        if node in visited:
            continue
        visited.add(node)
        edge=all_outputs.get(node)
        if edge is None:
            continue
        needed.add(edge)
        for inp in edge.inputs+edge.implicit_inputs+edge.order_only:
            if inp not in visited:
                stack.append(inp)
    edge_deps={}
    for e in needed:
        deps=[]
        for inp in e.inputs+e.implicit_inputs+e.order_only:
            de=all_outputs.get(inp)
            if de and de in needed:
                deps.append(de)
        edge_deps[e]=deps
    in_deg={e: len(edge_deps[e]) for e in needed}
    rev=collections.defaultdict(list)
    for e,deps in edge_deps.items():
        for d in deps:
            rev[d].append(e)
    from collections import deque
    q=deque([e for e,d in in_deg.items() if d==0])
    topo=[]
    while q:
        e=q.popleft()
        topo.append(e)
        for dep in rev[e]:
            in_deg[dep]-=1
            if in_deg[dep]==0:
                q.append(dep)
    if only_final:
        for t in targets:
            edge=all_outputs.get(t)
            if edge:
                cmd=expand_edge_command_simple(edge,parser)
                sys.stdout.write(f"{cmd}\n")
    else:
        for edge in topo:
            cmd=expand_edge_command_simple(edge,parser)
            if cmd:
                sys.stdout.write(f"{cmd}\n")
    return 0

def tool_inputs(parser, args, options):
    print0=False
    no_escape=False
    dep_order=False
    targets=[]
    i=0
    while i < len(args):
        arg=args[i]
        if arg in ('-0','--print0'):
            print0=True
            i+=1
        elif arg in ('-E','--no-shell-escape'):
            no_escape=True
            i+=1
        elif arg in ('-d','--dependency-order'):
            dep_order=True
            i+=1
        elif arg in ('-h','--help'):
            sys.stdout.write("Usage '-t inputs [options] [targets]\n\nList all inputs used for a set of targets, sorted in dependency order.\nNote that by default, results are shell escaped, and sorted alphabetically,\nand never include validation target paths.\n\nOptions:\n  -h, --help          Print this message.\n  -0, --print0            Use \\0, instead of \\n as a line terminator.\n  -E, --no-shell-escape   Do not shell escape the result.\n  -d, --dependency-order  Sort results by dependency order.\n")
            sys.exit(0)
        elif arg.startswith('-'):
            sys.stderr.write(f"inputs: invalid option -- '{arg[1]}'\n")
            sys.exit(1)
        else:
            targets.append(arg)
            i+=1
    if not targets:
        if parser.defaults:
            targets=parser.defaults
        else:
            all_outputs=set(parser.outputs_seen.keys())
            all_inputs=set()
            for edge in parser.edges:
                all_inputs.update(edge.inputs)
                all_inputs.update(edge.implicit_inputs)
                all_inputs.update(edge.order_only)
            roots=[out for out in all_outputs if out not in all_inputs]
            targets=roots if roots else list(all_outputs)
    all_outputs=parser.outputs_seen
    inputs_set=set()
    order_list=[]
    visited=set()
    def collect(node):
        if node in visited:
            return
        visited.add(node)
        edge=all_outputs.get(node)
        if edge is None:
            return
        for inp in edge.inputs+edge.implicit_inputs+edge.order_only:
            if inp not in inputs_set:
                inputs_set.add(inp)
                order_list.append(inp)
            if inp in all_outputs:
                collect(inp)
    for t in targets:
        edge=all_outputs.get(t)
        if edge:
            for inp in edge.inputs+edge.implicit_inputs+edge.order_only:
                if inp not in inputs_set:
                    inputs_set.add(inp)
                    order_list.append(inp)
                if inp in all_outputs:
                    collect(inp)
    result=order_list if dep_order else sorted(inputs_set)
    term='\0' if print0 else '\n'
    for inp in result:
        out=shell_quote(inp) if not no_escape else inp
        sys.stdout.write(out+term)
    return 0

def tool_multi_inputs(parser, args, options):
    print0=False
    delimiter='\t'
    targets=[]
    i=0
    while i < len(args):
        arg=args[i]
        if arg in ('--print0','-0'):
            print0=True
            i+=1
        elif arg.startswith('--delimiter='):
            delimiter=arg.split('=',1)[1]
            i+=1
        elif arg in ('--delimiter','-d'):
            if i+1>=len(args):
                sys.stderr.write("multi-inputs: missing delimiter\n")
                sys.exit(1)
            delimiter=args[i+1]
            i+=2
        elif arg in ('-h','--help'):
            sys.stdout.write("Usage '-t multi-inputs [options] [targets]\n\nPrint one or more sets of inputs required to build targets, sorted in dependency order.\nThe tool works like inputs tool but with addition of the target for each line.\nThe output will be a series of lines with the following elements:\n<target> <delimiter> <input> <terminator>\nNote that a given input may appear for several targets if it is used by more than one targets.\nOptions:\n  -h, --help                   Print this message.\n  -d  --delimiter=DELIM        Use DELIM instead of TAB for field delimiter.\n  -0, --print0                 Use \\0, instead of \\n as a line terminator.\n")
            sys.exit(0)
        elif arg.startswith('-'):
            sys.stderr.write(f"multi-inputs: invalid option -- '{arg[1]}'\n")
            sys.exit(1)
        else:
            targets.append(arg)
            i+=1
    if not targets:
        if parser.defaults:
            targets=parser.defaults
        else:
            all_outputs=set(parser.outputs_seen.keys())
            all_inputs=set()
            for edge in parser.edges:
                all_inputs.update(edge.inputs)
                all_inputs.update(edge.implicit_inputs)
                all_inputs.update(edge.order_only)
            roots=[out for out in all_outputs if out not in all_inputs]
            targets=roots if roots else list(all_outputs)
    all_outputs=parser.outputs_seen
    term='\0' if print0 else '\n'
    for t in targets:
        inputs_set=set()
        order_list=[]
        visited=set()
        def collect(node):
            if node in visited:
                return
            visited.add(node)
            edge=all_outputs.get(node)
            if edge is None:
                return
            for inp in edge.inputs+edge.implicit_inputs+edge.order_only:
                if inp not in inputs_set:
                    inputs_set.add(inp)
                    order_list.append(inp)
                if inp in all_outputs:
                    collect(inp)
        edge=all_outputs.get(t)
        if edge:
            for inp in edge.inputs+edge.implicit_inputs+edge.order_only:
                if inp not in inputs_set:
                    inputs_set.add(inp)
                    order_list.append(inp)
                if inp in all_outputs:
                    collect(inp)
        for inp in order_list:
            sys.stdout.write(f"{t}{delimiter}{inp}{term}")
    return 0

