class FileContext:
    def __init__(self, path, parent=None):
        self.path=path
        self.vars={}
        self.rules={}
        self.pools={}
        self.parent=parent
    def lookup_var_dict(self):
        d={}
        chain=[]
        ctx=self
        while ctx is not None:
            chain.append(ctx)
            ctx=ctx.parent
        for ctx in reversed(chain):
            d.update(ctx.vars)
        return d
    def lookup_rule(self, name):
        ctx=self
        while ctx is not None:
            if name in ctx.rules:
                return ctx.rules[name]
            ctx=ctx.parent
        return None

