                    explicit_str=outputs_part
                    implicit_str=""
                explicit_raw=tokenize_paths(explicit_str,fpath,lineno,text,self.required_version) if explicit_str.strip() else []
                implicit_raw=tokenize_paths(implicit_str,fpath,lineno,text,self.required_version) if implicit_str.strip() else []
                visible=context.lookup_var_dict()
                explicit_outputs=[]
                for tok in explicit_raw:
                    exp=expand_vars(tok,visible,self.required_version,fpath,lineno,text)
                    if exp!="":
                        explicit_outputs.append(exp)
                implicit_outputs=[]
                for tok in implicit_raw:
                    exp=expand_vars(tok,visible,self.required_version,fpath,lineno,text)
