                rest=stripped[8:].strip()
                if not rest:
                    raise ParseError(fpath,lineno,"expected target name",text)
                tokens_raw=tokenize_paths(rest,fpath,lineno,text,self.required_version)
                visible=context.lookup_var_dict()
