def tool_missingdeps(parser, args, options):
    sys.stdout.write(f"Processed {len(parser.edges)} nodes.\n")
    sys.stdout.write("No missing dependencies on generated files found.\n")
    return 0

def tool_graph(parser, args, options):
    targets=args
    all_outputs=parser.outputs_seen
    if not targets:
        all_out_set=set(all_outputs.keys())
        all_in=set()
        for edge in parser.edges:
            all_in.update(edge.inputs)
            all_in.update(edge.implicit_inputs)
            all_in.update(edge.order_only)
        roots=[out for out in all_out_set if out not in all_in]
        targets=roots
    visited_nodes=set()
    visited_edges=set()
    stack=list(targets)
    while stack:
        node=stack.pop()
        if node in visited_nodes:
            continue
        visited_nodes.add(node)
        edge=all_outputs.get(node)
        if edge is None:
            continue
        visited_edges.add(edge)
        for inp in edge.inputs+edge.implicit_inputs+edge.order_only:
            if inp not in visited_nodes:
                stack.append(inp)
    sys.stdout.write("digraph ninja {\n")
    sys.stdout.write('rankdir="LR"\n')
    sys.stdout.write('node [fontsize=10, shape=box, height=0.25]\n')
    sys.stdout.write('edge [fontsize=10]\n')
    node_id_map={}
    next_id=0
    def get_id(p):
        nonlocal next_id
        if p not in node_id_map:
            node_id_map[p]=f"0x{next_id:08x}"
            next_id+=1
        return node_id_map[p]
    for node in visited_nodes:
        nid=get_id(node)
        label=node.replace('"','\\"')
        sys.stdout.write(f'"{nid}" [label="{label}"]\n')
    for edge in visited_edges:
        rid=f"0x{next_id:08x}"
        next_id+=1
        sys.stdout.write(f'"{rid}" [label="{edge.rule_name}", shape=ellipse]\n')
        for out in edge.outputs+edge.implicit_outputs:
            if out in visited_nodes:
                oid=get_id(out)
                sys.stdout.write(f'"{rid}" -> "{oid}"\n')
        for inp in edge.inputs+edge.implicit_inputs+edge.order_only:
            if inp in visited_nodes:
                iid=get_id(inp)
                sys.stdout.write(f'"{iid}" -> "{rid}" [arrowhead=none]\n')
    sys.stdout.write("}\n")
    return 0

def tool_query(parser, args, options):
    if not args:
        sys.stderr.write("ninja: error: expected a target to query\n")
        sys.exit(1)
    target=args[0]
    edge=parser.outputs_seen.get(target)
    if edge is None:
        sys.stderr.write(f"ninja: error: unknown target '{target}'\n")
        sys.exit(1)
    sys.stdout.write(f"{target}:\n")
    sys.stdout.write(f"  input: {edge.rule_name}\n")
    for inp in edge.inputs:
        sys.stdout.write(f"    {inp}\n")
    if edge.implicit_inputs:
        sys.stdout.write(f"    | {' '.join(edge.implicit_inputs)}\n")
    if edge.order_only:
        sys.stdout.write(f"    || {' '.join(edge.order_only)}\n")
    if edge.validations:
        sys.stdout.write(f"    |@ {' '.join(edge.validations)}\n")
    outs=[]
    for e in parser.edges:
        if target in e.inputs or target in e.implicit_inputs or target in e.order_only:
            outs.extend(e.outputs)
            outs.extend(e.implicit_outputs)
    sys.stdout.write(f"  outputs:\n")
    for o in outs:
        sys.stdout.write(f"    {o}\n")
    return 0

def tool_rules(parser, args, options):
    show_desc=False
    i=0
    while i < len(args):
        arg=args[i]
        if arg=='-d':
            show_desc=True
            i+=1
        elif arg=='-h':
            sys.stdout.write("usage: ninja -t rules [options]\n\n")
            sys.stdout.write("options:\n")
            sys.stdout.write("  -d     also print the description of the rule\n")
            sys.stdout.write("  -h     print this message\n")
            sys.exit(0)
        else:
            sys.stderr.write(f"rules: invalid option -- '{arg[1]}'\n")
            sys.stderr.write("usage: ninja -t rules [options]\n\n")
            sys.stderr.write("options:\n")
            sys.stderr.write("  -d     also print the description of the rule\n")
            sys.stderr.write("  -h     print this message\n")
            sys.exit(1)
    rule_objs={}
    rule_objs['phony']=None
    visited=set()
    def collect(ctx):
        if ctx in visited:
            return
        visited.add(ctx)
        for rn,ro in ctx.rules.items():
            rule_objs[rn]=ro
        if ctx.parent:
            collect(ctx.parent)
    for edge in parser.edges:
        if edge.file_context:
            collect(edge.file_context)
    for rn in sorted(rule_objs.keys()):
        if show_desc:
            ro=rule_objs[rn]
            desc=ro.vars.get('description','') if ro else ''
            sys.stdout.write(f"{rn}: {desc}\n")
        else:
            sys.stdout.write(f"{rn}\n")
    return 0

def tool_compdb(parser, args, options):
    rules_filter=[]
    i=0
    while i < len(args):
        arg=args[i]
        if arg=='-x':
            i+=1
        elif arg.startswith('-'):
            sys.stderr.write(f"compdb: invalid option -- '{arg[1]}'\n")
            sys.stderr.write("usage: ninja -t compdb [options] [rules]\n\n")
            sys.stderr.write("options:\n")
            sys.stderr.write("  -x     expand @rspfile style response file invocations\n")
            sys.exit(1)
        else:
            rules_filter.append(arg)
            i+=1
    entries=[]
    cwd=os.getcwd()
    for edge in parser.edges:
        if rules_filter and edge.rule_name not in rules_filter:
            continue
        if edge.rule_name=='phony':
            continue
        if edge.file_context.lookup_rule(edge.rule_name) is None:
            continue
        file_ctx=edge.file_context
        in_quoted=' '.join(shell_quote(p) for p in edge.inputs)
        out_quoted=' '.join(shell_quote(p) for p in edge.outputs)
        builtins={'in': in_quoted, 'out': out_quoted, 'in_newline': '\n'.join(edge.inputs)}
        combined=dict(file_ctx.lookup_var_dict())
        combined.update(edge.variables)
        combined.update(builtins)
        rule_obj=file_ctx.lookup_rule(edge.rule_name)
        exp_vars={}
        for k,v in rule_obj.vars.items():
            d=dict(combined)
            d.update(exp_vars)
            try:
                exp=expand_vars(v,d,parser.required_version,edge.filename,edge.lineno,"")
            except ParseError:
                exp=v
            exp_vars[k]=exp
        cmd=exp_vars.get('command','')
        if not cmd:
            continue
        for inp in edge.inputs:
            out=edge.outputs[0] if edge.outputs else ""
            entries.append({"directory": cwd, "command": cmd, "file": inp, "output": out})
    sys.stdout.write("[\n")
    for idx,ent in enumerate(entries):
        json.dump(ent, sys.stdout, indent=2)
        if idx!=len(entries)-1:
            sys.stdout.write(",\n")
        else:
            sys.stdout.write("\n")
    sys.stdout.write("]\n")
    return 0

def tool_compdb_targets(parser, args, options):
    targets=[]
    i=0
    while i < len(args):
        arg=args[i]
        if arg=='-x':
            i+=1
        elif arg=='-h':
            sys.stdout.write("usage: ninja -t compdb [-hx] target [targets]\n\n")
            sys.stdout.write("options:\n")
            sys.stdout.write("  -h     display this help message\n")
            sys.stdout.write("  -x     expand @rspfile style response file invocations\n")
            sys.exit(0)
        elif arg.startswith('-'):
            sys.stderr.write(f"compdb-targets: invalid option -- '{arg[1]}'\n")
            sys.stderr.write("usage: ninja -t compdb [-hx] target [targets]\n\n")
            sys.stderr.write("options:\n")
            sys.stderr.write("  -h     display this help message\n")
            sys.stderr.write("  -x     expand @rspfile style response file invocations\n")
            sys.exit(1)
        else:
            targets.append(arg)
            i+=1
    if not targets:
        sys.stderr.write("compdb-targets: expected at least one target\n")
        sys.exit(1)
    all_outputs=parser.outputs_seen
    needed=set()
    visited=set()
    stack=list(targets)
    while stack:
        node=stack.pop()
        if node in visited:
            continue
        visited.add(node)
        edge=all_outputs.get(node)
        if edge is None:
            continue
        needed.add(edge)
        for inp in edge.inputs+edge.implicit_inputs+edge.order_only:
            if inp not in visited:
                stack.append(inp)
    entries=[]
    cwd=os.getcwd()
    for edge in needed:
        if edge.rule_name=='phony':
            continue
        if edge.file_context.lookup_rule(edge.rule_name) is None:
            continue
        file_ctx=edge.file_context
        in_quoted=' '.join(shell_quote(p) for p in edge.inputs)
        out_quoted=' '.join(shell_quote(p) for p in edge.outputs)
        builtins={'in': in_quoted, 'out': out_quoted, 'in_newline': '\n'.join(edge.inputs)}
        combined=dict(file_ctx.lookup_var_dict())
        combined.update(edge.variables)
        combined.update(builtins)
        rule_obj=file_ctx.lookup_rule(edge.rule_name)
        exp_vars={}
        for k,v in rule_obj.vars.items():
            d=dict(combined)
            d.update(exp_vars)
            try:
                exp=expand_vars(v,d,parser.required_version,edge.filename,edge.lineno,"")
            except ParseError:
                exp=v
            exp_vars[k]=exp
        cmd=exp_vars.get('command','')
        if not cmd:
            continue
        for inp in edge.inputs:
            out=edge.outputs[0] if edge.outputs else ""
            entries.append({"directory": cwd, "command": cmd, "file": inp, "output": out})
    sys.stdout.write("[\n")
    for idx,ent in enumerate(entries):
        json.dump(ent, sys.stdout, indent=2)
        if idx!=len(entries)-1:
            sys.stdout.write(",\n")
        else:
            sys.stdout.write("\n")
    sys.stdout.write("]\n")
    return 0

