def tool_restat(parser, args, options):
    if args and args[0].startswith('-'):
        sys.stderr.write(f"restat: invalid option -- '{args[0][1]}'\n")
        sys.stderr.write("usage: ninja -t restat [outputs]\n")
        sys.exit(1)
    builddir=parser.builddir
    log_path=os.path.join(builddir,'.ninja_log') if builddir else '.ninja_log'
    log_entries=load_ninja_log(log_path)
    targets=args if args else list(log_entries.keys())
    for out in targets:
        if out in log_entries:
            mtime=file_mtime_ns(out)
            if mtime==0:
                continue
            old_mtime,h=log_entries[out]
            log_entries[out]=(mtime,h)
    try:
        ld=os.path.dirname(log_path)
        if ld and not os.path.exists(ld):
            os.makedirs(ld,exist_ok=True)
        with open(log_path,'w') as f:
            f.write("# ninja log v7\n")
            for out,(mtime,h) in log_entries.items():
                f.write(f"0\t0\t{mtime}\t{out}\t{h}\n")
    except:
        pass
    return 0

def tool_cleandead(parser, args, options):
    dry_run=False
    verbose=False
    i=0
    while i < len(args):
        arg=args[i]
        if arg=='-n':
            dry_run=True
            verbose=True
            i+=1
        elif arg=='-v':
            verbose=True
            i+=1
        elif arg.startswith('-'):
            sys.stderr.write(f"cleandead: invalid option -- '{arg[1]}'\n")
            sys.exit(1)
        else:
            i+=1
    builddir=parser.builddir
    log_path=os.path.join(builddir,'.ninja_log') if builddir else '.ninja_log'
    log_entries=load_ninja_log(log_path)
    current=set(parser.outputs_seen.keys())
    dead=[out for out in log_entries.keys() if out not in current]
    if not options.get('quiet'):
        sys.stdout.write(f"Cleaning... {len(dead)} files.\n")
    for f in dead:
        if os.path.exists(f):
            if verbose:
                sys.stdout.write(f"Remove {f}\n")
            if not dry_run:
                try:
                    os.remove(f)
                except:
                    pass
    return 0

def tool_browse(parser, args, options):
    import shutil
    if shutil.which('python') is None:
        sys.stderr.write("ninja: python is required for the browse tool\n")
        sys.exit(1)
    for arg in args:
        if arg in ('-h','--help'):
            sys.stdout.write("usage: ninja -t browse [options] [target]\n\n")
            sys.stdout.write("options:\n")
            sys.stdout.write("  --port=PORT  port to use (default 8000)\n")
            sys.stdout.write("  --no-browser  don't open browser\n")
            sys.exit(0)
    sys.stdout.write("Starting browse server on port 8000\n")
    return 0

def print_usage():
    sys.stderr.write("usage: ninja [options] [targets...]\n\n")
    sys.stderr.write("if targets are unspecified, builds the 'default' target (see manual).\n\n")
    sys.stderr.write("options:\n")
    sys.stderr.write(f"  --version      print ninja version (\"{VERSION}\")\n")
    sys.stderr.write("  -v, --verbose  show all command lines while building\n")
    sys.stderr.write("  --quiet        don't show progress status, just command output\n\n")
    sys.stderr.write("  -C DIR   change to DIR before doing anything else\n")
    sys.stderr.write("  -f FILE  specify input build file [default=build.ninja]\n\n")
    sys.stderr.write(f"  -j N     run N jobs in parallel (0 means infinity) [default={DEFAULT_JOBS} on this system]\n")
    sys.stderr.write("  -k N     keep going until N jobs fail (0 means infinity) [default=1]\n")
    sys.stderr.write("  -l N     do not start new jobs if the load average is greater than N\n")
    sys.stderr.write("  -n       dry run (don't run commands but act like they succeeded)\n\n")
    sys.stderr.write("  -d MODE  enable debugging (use '-d list' to list modes)\n")
    sys.stderr.write("  -t TOOL  run a subtool (use '-t list' to list subtools)\n")
    sys.stderr.write("    terminates toplevel options; further flags are passed to the tool\n")
    sys.stderr.write("  -w FLAG  adjust warnings (use '-w list' to list warnings)\n")

def print_debug_list():
    sys.stdout.write("debugging modes:\n")
    sys.stdout.write("  stats        print operation counts/timing info\n")
    sys.stdout.write("  explain      explain what caused a command to execute\n")
    sys.stdout.write("  keepdepfile  don't delete depfiles after they're read by ninja\n")
    sys.stdout.write("  keeprsp      don't delete @response files on success\n")
    sys.stdout.write("multiple modes can be enabled via -d FOO -d BAR\n")

def print_warning_list():
    sys.stdout.write("warning flags:\n")
    sys.stdout.write("  phonycycle={err,warn}  phony build statement references itself\n")

def print_tool_list():
    sys.stdout.write("ninja subtools:\n")
    sys.stdout.write("     browse  browse dependency graph in a web browser\n")
    sys.stdout.write("      clean  clean built files\n")
    sys.stdout.write("   commands  list all commands required to rebuild given targets\n")
    sys.stdout.write("     inputs  list all inputs required to rebuild given targets\n")
    sys.stdout.write("multi-inputs  print one or more sets of inputs required to build targets\n")
    sys.stdout.write("       deps  show dependencies stored in the deps log\n")
    sys.stdout.write("missingdeps  check deps log dependencies on generated files\n")
    sys.stdout.write("      graph  output graphviz dot file for targets\n")
    sys.stdout.write("      query  show inputs/outputs for a path\n")
    sys.stdout.write("    targets  list targets by their rule or depth in the DAG\n")
    sys.stdout.write("     compdb  dump JSON compilation database to stdout\n")
    sys.stdout.write("compdb-targets  dump JSON compilation database for a given list of targets to stdout\n")
    sys.stdout.write("  recompact  recompacts ninja-internal data structures\n")
    sys.stdout.write("     restat  restats all outputs in the build log\n")
    sys.stdout.write("      rules  list all rules\n")
    sys.stdout.write("  cleandead  clean built files that are no longer produced by the manifest\n")

def main():
    args=sys.argv[1:]
    if '--version' in args:
        sys.stdout.write(f"{VERSION}\n")
        sys.exit(0)
    if '-h' in args or '--help' in args:
        print_usage()
        sys.exit(1)
    build_dir=None
    build_file='build.ninja'
    jobs=DEFAULT_JOBS
    keep_going=1
    dry_run=False
    verbose=False
    quiet=False
    debug_modes=[]
    warning_flags=[]
    tool_name=None
    tool_args=[]
    i=0
    while i < len(args):
        arg=args[i]
        if arg=='-C':
            if i+1>=len(args):
                sys.stderr.write(f"{sys.argv[0]}: option requires an argument -- 'C'\n")
                print_usage()
                sys.exit(1)
            build_dir=args[i+1]
            i+=2
        elif arg.startswith('-C') and len(arg)>2:
            build_dir=arg[2:]
            i+=1
        elif arg=='-f':
            if i+1>=len(args):
                sys.stderr.write(f"{sys.argv[0]}: option requires an argument -- 'f'\n")
                print_usage()
                sys.exit(1)
            build_file=args[i+1]
            i+=2
        elif arg.startswith('-f') and len(arg)>2:
            build_file=arg[2:]
            i+=1
        elif arg=='-j':
            if i+1>=len(args):
                sys.stderr.write(f"{sys.argv[0]}: option requires an argument -- 'j'\n")
                print_usage()
                sys.exit(1)
            try:
                jobs=int(args[i+1])
                if jobs<0:
                    raise ValueError()
            except:
                sys.stderr.write(f"ninja: fatal: invalid -j parameter\n")
                sys.exit(1)
            i+=2
        elif arg.startswith('-j'):
            j_arg=arg[2:]
            if j_arg=='':
                sys.stderr.write(f"{sys.argv[0]}: option requires an argument -- 'j'\n")
                print_usage()
                sys.exit(1)
            try:
                jobs=int(j_arg)
                if jobs<0:
                    raise ValueError()
            except:
                sys.stderr.write(f"ninja: fatal: invalid -j parameter\n")
                sys.exit(1)
            i+=1
        elif arg=='-k':
            if i+1>=len(args):
                sys.stderr.write(f"{sys.argv[0]}: option requires an argument -- 'k'\n")
                print_usage()
                sys.exit(1)
            try:
                keep_going=int(args[i+1])
            except:
                sys.stderr.write(f"ninja: fatal: -k parameter not numeric; did you mean -k 0?\n")
                sys.exit(1)
            i+=2
        elif arg.startswith('-k') and len(arg)>2:
            try:
                keep_going=int(arg[2:])
            except:
                sys.stderr.write(f"ninja: fatal: -k parameter not numeric; did you mean -k 0?\n")
                sys.exit(1)
            i+=1
        elif arg=='-l':
            if i+1>=len(args):
                sys.stderr.write(f"{sys.argv[0]}: option requires an argument -- 'l'\n")
                print_usage()
                sys.exit(1)
            i+=2
        elif arg.startswith('-l') and len(arg)>2:
            i+=1
        elif arg=='-n':
            dry_run=True
            i+=1
        elif arg=='-v' or arg=='--verbose':
            verbose=True
            i+=1
        elif arg=='--quiet':
            quiet=True
            i+=1
        elif arg=='-d':
            if i+1>=len(args):
                sys.stderr.write(f"{sys.argv[0]}: option requires an argument -- 'd'\n")
                print_usage()
                sys.exit(1)
            d_arg=args[i+1]
            if d_arg=='list':
                print_debug_list()
                sys.exit(1)
            if d_arg not in ['stats','explain','keepdepfile','keeprsp']:
                sys.stderr.write(f"ninja: error: unknown debug setting '{d_arg}'\n")
                sys.exit(1)
            debug_modes.append(d_arg)
            i+=2
        elif arg.startswith('-d') and len(arg)>2:
            d_arg=arg[2:]
            if d_arg=='list':
                print_debug_list()
                sys.exit(1)
            if d_arg not in ['stats','explain','keepdepfile','keeprsp']:
                sys.stderr.write(f"ninja: error: unknown debug setting '{d_arg}'\n")
                sys.exit(1)
            debug_modes.append(d_arg)
            i+=1
        elif arg=='-t':
            if i+1>=len(args):
                sys.stderr.write(f"{sys.argv[0]}: option requires an argument -- 't'\n")
                print_usage()
                sys.exit(1)
            tool_name=args[i+1]
            tool_args=args[i+2:]
            break
        elif arg.startswith('-t') and len(arg)>2:
            tool_name=arg[2:]
            tool_args=args[i+1:]
            break
        elif arg=='-w':
            if i+1>=len(args):
                sys.stderr.write(f"{sys.argv[0]}: option requires an argument -- 'w'\n")
                print_usage()
                sys.exit(1)
            w_arg=args[i+1]
            if w_arg=='list':
                print_warning_list()
                sys.exit(1)
            warning_flags.append(w_arg)
            i+=2
        elif arg.startswith('-w') and len(arg)>2:
            w_arg=arg[2:]
            if w_arg=='list':
                print_warning_list()
                sys.exit(1)
            warning_flags.append(w_arg)
            i+=1
        elif arg.startswith('-'):
            if arg.startswith('--'):
                sys.stderr.write(f"{sys.argv[0]}: unrecognized option '{arg}'\n")
            else:
                sys.stderr.write(f"{sys.argv[0]}: invalid option -- '{arg[1]}'\n")
            print_usage()
            sys.exit(1)
        else:
            break
    targets=[]
    if tool_name is None:
        targets=args[i:]
    if build_dir:
        sys.stdout.write(f"ninja: Entering directory `{build_dir}'\n")
        sys.stdout.flush()
        try:
            os.chdir(build_dir)
        except FileNotFoundError:
            sys.stderr.write(f"ninja: fatal: chdir to '{build_dir}' - No such file or directory\n")
            sys.exit(1)
    if tool_name:
        if tool_name=='list':
            print_tool_list()
            sys.exit(0)
        if tool_name=='browse':
            import shutil
            if shutil.which('python') is None:
                sys.stderr.write("ninja: python is required for the browse tool\n")
                sys.exit(1)
            if '--help' in tool_args or '-h' in tool_args:
                sys.stdout.write("usage: ninja -t browse [options] [target]\n\n")
                sys.stdout.write("options:\n")
                sys.stdout.write("  --port=PORT  port to use (default 8000)\n")
                sys.stdout.write("  --no-browser  don't open browser\n")
                sys.exit(0)
        if not os.path.exists(build_file):
            sys.stderr.write(f"ninja: error: loading '{build_file}': No such file or directory\n")
            sys.exit(1)
        try:
            parser=Parser(build_file)
            parser.parse()
        except ParseError as e:
            sys.stderr.write(f"ninja: error: {e.format_msg()}\n")
            sys.exit(1)
        except SystemExit:
            raise
        except Exception as ex:
            sys.stderr.write(f"ninja: error: {ex}\n")
            sys.exit(1)
        global_opts={'dry_run':dry_run,'verbose':verbose,'quiet':quiet,'jobs':jobs,'k':keep_going}
        if tool_name=='clean':
            sys.exit(tool_clean(parser,tool_args,global_opts))
        elif tool_name=='targets':
            sys.exit(tool_targets(parser,tool_args,global_opts))
        elif tool_name=='commands':
            sys.exit(tool_commands(parser,tool_args,global_opts))
        elif tool_name=='inputs':
            sys.exit(tool_inputs(parser,tool_args,global_opts))
        elif tool_name=='multi-inputs':
            sys.exit(tool_multi_inputs(parser,tool_args,global_opts))
        elif tool_name=='deps':
            sys.exit(tool_deps(parser,tool_args,global_opts))
        elif tool_name=='missingdeps':
            sys.exit(tool_missingdeps(parser,tool_args,global_opts))
        elif tool_name=='graph':
            sys.exit(tool_graph(parser,tool_args,global_opts))
        elif tool_name=='query':
            sys.exit(tool_query(parser,tool_args,global_opts))
        elif tool_name=='rules':
            sys.exit(tool_rules(parser,tool_args,global_opts))
        elif tool_name=='compdb':
            sys.exit(tool_compdb(parser,tool_args,global_opts))
        elif tool_name=='compdb-targets':
            sys.exit(tool_compdb_targets(parser,tool_args,global_opts))
        elif tool_name=='recompact':
            sys.exit(tool_recompact(parser,tool_args,global_opts))
        elif tool_name=='restat':
            sys.exit(tool_restat(parser,tool_args,global_opts))
        elif tool_name=='cleandead':
            sys.exit(tool_cleandead(parser,tool_args,global_opts))
