        else:
            sys.stderr.write(f"ninja: fatal: unknown tool '{tool_name}'\n")
            sys.exit(1)
    if not os.path.exists(build_file):
        sys.stderr.write(f"ninja: error: loading '{build_file}': No such file or directory\n")
        sys.exit(1)
    try:
        parser=Parser(build_file)
        parser.parse()
    except ParseError as e:
        sys.stderr.write(f"ninja: error: {e.format_msg()}\n")
        sys.exit(1)
    except SystemExit:
        raise
    except Exception as ex:
        sys.stderr.write(f"ninja: error: {ex}\n")
        sys.exit(1)
    for edge in parser.edges:
        if edge.rule_name=='phony':
            for out in edge.outputs:
                if out in edge.inputs:
                    flag=None
                    for wf in warning_flags:
                        if wf.startswith('phonycycle='):
                            flag=wf.split('=',1)[1]
                            break
                    if flag=='warn':
                        sys.stderr.write(f"ninja: warning: phony target '{out}' names itself as an input; ignoring [-w phonycycle=warn]\n")
                    sys.stderr.write(f"ninja: error: could not determine root nodes of build graph\n")
                    sys.exit(1)
    bs=BuildSystem(parser,{'jobs':jobs,'k':keep_going,'verbose':verbose,'quiet':quiet,'dry_run':dry_run,'explain':'explain' in debug_modes,'keepdepfile':'keepdepfile' in debug_modes,'keeprsp':'keeprsp' in debug_modes})
    ret=bs.build(targets,jobs,verbose,quiet,dry_run,'explain' in debug_modes,'keepdepfile' in debug_modes,'keeprsp' in debug_modes)
    sys.exit(ret)

if __name__=='__main__':
